-- HOOKS LAB · instalación en Supabase (tablas + biblioteca inicial)
-- Pegar completo en Supabase → SQL Editor → Run. Ejecutar una sola vez en un proyecto nuevo.
begin;

CREATE TABLE public.brands (
    id integer NOT NULL,
    slug text NOT NULL,
    name text NOT NULL,
    kind text DEFAULT 'otra'::text NOT NULL,
    description text DEFAULT ''::text NOT NULL,
    audience text DEFAULT ''::text NOT NULL,
    personality text DEFAULT ''::text NOT NULL,
    tone text DEFAULT ''::text NOT NULL,
    products text DEFAULT ''::text NOT NULL,
    services text DEFAULT ''::text NOT NULL,
    value_prop text DEFAULT ''::text NOT NULL,
    allowed_words jsonb DEFAULT '[]'::jsonb NOT NULL,
    banned_words jsonb DEFAULT '[]'::jsonb NOT NULL,
    goals text DEFAULT ''::text NOT NULL,
    max_register text DEFAULT 'cafe'::text NOT NULL,
    spanish_variant text DEFAULT 'colombiano'::text NOT NULL,
    weights jsonb,
    created_at timestamp without time zone DEFAULT now() NOT NULL
);

CREATE SEQUENCE public.brands_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE public.brands_id_seq OWNED BY public.brands.id;

CREATE TABLE public.contents (
    id integer NOT NULL,
    hook_id integer NOT NULL,
    format text NOT NULL,
    title text DEFAULT ''::text NOT NULL,
    body text NOT NULL,
    slides jsonb,
    promise_check text DEFAULT ''::text NOT NULL,
    created_at timestamp without time zone DEFAULT now() NOT NULL
);

CREATE SEQUENCE public.contents_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE public.contents_id_seq OWNED BY public.contents.id;

CREATE TABLE public.creators (
    id integer NOT NULL,
    slug text NOT NULL,
    name text NOT NULL,
    handle text DEFAULT ''::text NOT NULL,
    country text DEFAULT ''::text NOT NULL,
    platforms jsonb DEFAULT '[]'::jsonb NOT NULL,
    category text DEFAULT ''::text NOT NULL,
    style text DEFAULT ''::text NOT NULL,
    mechanisms_observed jsonb DEFAULT '[]'::jsonb NOT NULL,
    notes text DEFAULT ''::text NOT NULL,
    show_name boolean DEFAULT true NOT NULL,
    status text DEFAULT 'perfil'::text NOT NULL,
    confidence text DEFAULT 'media'::text NOT NULL,
    sources jsonb DEFAULT '[]'::jsonb NOT NULL
);

CREATE SEQUENCE public.creators_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE public.creators_id_seq OWNED BY public.creators.id;

CREATE TABLE public.generated_hooks (
    id integer NOT NULL,
    generation_id integer NOT NULL,
    idx integer NOT NULL,
    text text NOT NULL,
    on_screen_text text,
    visual_action text,
    structure_code text,
    structure_name text DEFAULT ''::text NOT NULL,
    mechanisms jsonb DEFAULT '[]'::jsonb NOT NULL,
    tone text DEFAULT ''::text NOT NULL,
    why text DEFAULT ''::text NOT NULL,
    audience text DEFAULT ''::text NOT NULL,
    weakness text DEFAULT ''::text NOT NULL,
    platform_adaptation text DEFAULT ''::text NOT NULL,
    scores jsonb,
    totals jsonb,
    total real,
    flags jsonb DEFAULT '[]'::jsonb NOT NULL,
    judge_note text DEFAULT ''::text NOT NULL,
    favorite boolean DEFAULT false NOT NULL,
    created_at timestamp without time zone DEFAULT now() NOT NULL
);

CREATE SEQUENCE public.generated_hooks_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE public.generated_hooks_id_seq OWNED BY public.generated_hooks.id;

CREATE TABLE public.generations (
    id integer NOT NULL,
    brand_id integer,
    input jsonb NOT NULL,
    plan jsonb,
    prompt_versions jsonb,
    provider text,
    model text,
    status text DEFAULT 'pendiente'::text NOT NULL,
    error text,
    ranking jsonb,
    diversity jsonb,
    created_at timestamp without time zone DEFAULT now() NOT NULL
);

CREATE SEQUENCE public.generations_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE public.generations_id_seq OWNED BY public.generations.id;

CREATE TABLE public.industries (
    code text NOT NULL,
    name text NOT NULL,
    lexicon jsonb NOT NULL,
    tensions jsonb NOT NULL,
    taboos jsonb NOT NULL
);

CREATE TABLE public.llm_calls (
    id integer NOT NULL,
    provider text NOT NULL,
    model text NOT NULL,
    purpose text NOT NULL,
    prompt_key text,
    prompt_version integer,
    input_tokens integer,
    output_tokens integer,
    latency_ms integer,
    ok boolean NOT NULL,
    error text,
    created_at timestamp without time zone DEFAULT now() NOT NULL
);

CREATE SEQUENCE public.llm_calls_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE public.llm_calls_id_seq OWNED BY public.llm_calls.id;

CREATE TABLE public.mechanisms (
    code text NOT NULL,
    name text NOT NULL,
    description text NOT NULL,
    foundation text NOT NULL,
    source text NOT NULL,
    confidence text NOT NULL,
    caveat text DEFAULT ''::text NOT NULL
);

CREATE TABLE public.observed_hooks (
    id integer NOT NULL,
    creator_id integer,
    platform text NOT NULL,
    published_at text DEFAULT ''::text NOT NULL,
    text text NOT NULL,
    url text DEFAULT ''::text NOT NULL,
    mechanisms jsonb DEFAULT '[]'::jsonb NOT NULL,
    structure_code text,
    construction text DEFAULT ''::text NOT NULL,
    evidence text DEFAULT 'O'::text NOT NULL,
    confidence text DEFAULT 'media'::text NOT NULL,
    is_counter_example boolean DEFAULT false NOT NULL
);

CREATE SEQUENCE public.observed_hooks_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE public.observed_hooks_id_seq OWNED BY public.observed_hooks.id;

CREATE TABLE public.prompt_versions (
    id integer NOT NULL,
    key text NOT NULL,
    version integer NOT NULL,
    system text NOT NULL,
    template text NOT NULL,
    effort text DEFAULT 'high'::text NOT NULL,
    active boolean DEFAULT false NOT NULL,
    notes text DEFAULT ''::text NOT NULL,
    created_at timestamp without time zone DEFAULT now() NOT NULL
);

CREATE SEQUENCE public.prompt_versions_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE public.prompt_versions_id_seq OWNED BY public.prompt_versions.id;

CREATE TABLE public.structures (
    code text NOT NULL,
    family text NOT NULL,
    name text NOT NULL,
    formula text NOT NULL,
    mechanisms jsonb NOT NULL,
    objective jsonb NOT NULL,
    tones jsonb NOT NULL,
    industries jsonb NOT NULL,
    difficulty integer NOT NULL,
    example text NOT NULL,
    counter_example text NOT NULL,
    adapt_linkedin text NOT NULL,
    adapt_instagram text NOT NULL,
    adapt_tiktok text NOT NULL,
    adapt_facebook text NOT NULL,
    reference text DEFAULT ''::text NOT NULL,
    is_question boolean DEFAULT false NOT NULL
);

ALTER TABLE ONLY public.brands ALTER COLUMN id SET DEFAULT nextval('public.brands_id_seq'::regclass);

ALTER TABLE ONLY public.contents ALTER COLUMN id SET DEFAULT nextval('public.contents_id_seq'::regclass);

ALTER TABLE ONLY public.creators ALTER COLUMN id SET DEFAULT nextval('public.creators_id_seq'::regclass);

ALTER TABLE ONLY public.generated_hooks ALTER COLUMN id SET DEFAULT nextval('public.generated_hooks_id_seq'::regclass);

ALTER TABLE ONLY public.generations ALTER COLUMN id SET DEFAULT nextval('public.generations_id_seq'::regclass);

ALTER TABLE ONLY public.llm_calls ALTER COLUMN id SET DEFAULT nextval('public.llm_calls_id_seq'::regclass);

ALTER TABLE ONLY public.observed_hooks ALTER COLUMN id SET DEFAULT nextval('public.observed_hooks_id_seq'::regclass);

ALTER TABLE ONLY public.prompt_versions ALTER COLUMN id SET DEFAULT nextval('public.prompt_versions_id_seq'::regclass);

INSERT INTO public.brands (id, slug, name, kind, description, audience, personality, tone, products, services, value_prop, allowed_words, banned_words, goals, max_register, spanish_variant, weights, created_at) VALUES (1, 'andres-betancourt', 'Andrés Betancourt', 'marca_personal', 'Ejecutivo de Recursos Humanos con más de 15 años de experiencia, con cargos directivos regionales en Latinoamérica. LinkedIn Top Voice, emprendedor y mentor en LinkedIn, social selling y marca personal.', 'CEOs, gerentes generales, directores de RR. HH., consultores, fundadores B2B y equipos comerciales.', 'Directo, crítico, con criterio ejecutivo; provoca con fundamento; conoce las empresas por dentro.', 'Conversación de café entre ejecutivos: claro, con opinión, sin jerga corporativa ni frases motivacionales.', 'Mentorías, bootcamps, formación en social selling.', 'Optimización de perfiles de LinkedIn, estrategia de marca personal y contenidos, social selling, employer advocacy.', 'Convertir autoridad y relaciones en LinkedIn en oportunidades comerciales reales, con mirada de ejecutivo, no de influencer.', '["ojo", "la verdad es que", "seamos honestos", "lo digo con cariño"]', '["sinergia", "apalancar", "potenciar", "líder de pensamiento", "en el dinámico mundo de hoy", "es fundamental", "hoy quiero compartirles"]', 'Leads calificados para servicios de LinkedIn y para QUBE; posicionamiento como referente ejecutivo.', 'cafe', 'colombiano', NULL, '2026-11-05 03:21:04.778479');
INSERT INTO public.brands (id, slug, name, kind, description, audience, personality, tone, products, services, value_prop, allowed_words, banned_words, goals, max_register, spanish_variant, weights, created_at) VALUES (2, 'qube', 'QUBE C-Level Advisory', 'qube', 'Firma de asesoría ejecutiva y transformación organizacional (Edgar Andrés Betancourt y Johanna Quintero). Une Strategy, Growth y Bio-Strategy: la dimensión humana y sistémica de los resultados.', 'Empresarios, CEOs y equipos directivos; empresas familiares y regionales (Bogotá, Orinoquía).', 'Socio estratégico exigente; habla de problemas de negocio, no de técnicas; serio sin ser acartonado.', 'Profesional cercano: lenguaje que entiende un CEO en un almuerzo, con criterio y sin promesas vacías.', 'Diagnóstico o auditoría; sprint de intervención de ~8 semanas hasta el Go-Live; advisory recurrente.', 'Alineación ejecutiva, gobierno, crecimiento comercial, dinámicas de poder y conflictos en equipos directivos.', 'Intervenciones cerradas con alcance, entregables e indicadores, que conectan estrategia, crecimiento y factores humanos.', '[]', '["soluciones integrales", "acompañamiento integral", "sinergia", "transformación digital", "holístico", "disruptivo"]', 'Autoridad ante CEOs y conversaciones comerciales con cuentas objetivo (ABM).', 'cercano', 'colombiano', NULL, '2026-11-05 03:21:04.780576');
INSERT INTO public.brands (id, slug, name, kind, description, audience, personality, tone, products, services, value_prop, allowed_words, banned_words, goals, max_register, spanish_variant, weights, created_at) VALUES (3, 'serena', 'Serena', 'serena', 'Comunidad de mujeres (WhatsApp) creada por Ps. Joha Quintero sobre bienestar, identidad, familia y trabajo. Pilares: YO, MI CUERPO, MI FAMILIA, MI TRABAJO, MI BIENESTAR Y TRANSFORMACIÓN.', 'Mujeres profesionales de 30 a 50 años, con responsabilidades laborales y familiares.', 'Empática, cercana, profunda; habla de lo cotidiano sin infantilizar ni dramatizar.', 'Sobremesa entre amigas que se conocen bien: cálido, honesto, con ejemplos de la vida real.', 'Comunidad gratuita; programas y productos de bienestar en validación (p. ej., El Mapa Energético Familiar).', 'Contenidos, encuentros y herramientas prácticas de bienestar.', 'Ayudar a las mujeres a reconocer patrones, entender lo que les pasa y encontrar herramientas concretas para actuar.', '[]', '["empoderada", "diosa", "vibra alta", "solo depende de ti", "sanar tu niña interior"]', 'Identificación emocional, participación y crecimiento de la comunidad.', 'sobremesa', 'colombiano', NULL, '2026-11-05 03:21:04.781759');
INSERT INTO public.brands (id, slug, name, kind, description, audience, personality, tone, products, services, value_prop, allowed_words, banned_words, goals, max_register, spanish_variant, weights, created_at) VALUES (4, 'joha-quintero', 'Ps. Joha Quintero', 'marca_personal', 'Psicóloga con experiencia en Recursos Humanos, desarrollo laboral, bienestar y clima organizacional; enfoque sistémico familiar y organizacional.', 'Mujeres profesionales; líderes de RR. HH. y bienestar.', 'Empática, profesional, reflexiva; explica sin sonar a clase académica.', 'Conversación cercana con criterio profesional.', 'Programas de bienestar, talleres.', 'Intervenciones de bienestar y clima; acompañamiento psicológico.', 'Psicología aplicada a la vida real: trabajo, familia y bienestar.', '[]', '["empoderada", "vibra alta", "solo depende de ti"]', 'Autoridad profesional y confianza.', 'cafe', 'colombiano', NULL, '2026-11-05 03:21:04.783093');

