INSERT INTO public.industries (code, name, lexicon, tensions, taboos) VALUES ('marketing', 'Marketing', '["alcance", "leads", "embudo", "contenido", "pauta", "CPA", "conversión", "marca"]', '["likes que no pagan facturas", "contenido para el algoritmo vs. para el cliente", "pautar sin oferta clara", "copiar al competidor"]', '["''el contenido es el rey''", "''engagement'' como fin", "métricas de vanidad presentadas como éxito"]');
