INSERT INTO public.industries (code, name, lexicon, tensions, taboos) VALUES ('bienestar', 'Bienestar', '["descanso", "energía", "rutina", "hábitos", "cansancio", "estrés", "pausa"]', '["autocuidado como otra tarea más en la lista", "descansar con culpa", "rutinas imposibles de influencer"]', '["positivismo tóxico", "''solo depende de ti''", "promesas médicas"]');
INSERT INTO public.industries (code, name, lexicon, tensions, taboos) VALUES ('salud', 'Salud', '["consulta", "síntoma", "chequeo", "EPS", "prevención", "tratamiento"]', '["ir al médico solo cuando ya es tarde", "información contradictoria en redes", "el paciente que no sigue el tratamiento"]', '["consejos médicos sin profesional", "cifras de salud sin fuente", "miedo como gancho"]');
INSERT INTO public.industries (code, name, lexicon, tensions, taboos) VALUES ('educacion', 'Educación', '["clase", "estudiante", "profesor", "título", "curso", "aprendizaje", "nota"]', '["títulos vs. habilidades", "aprender de memoria vs. entender", "cursos que nadie termina"]', '["''la universidad no sirve''", "promesas de empleo garantizado"]');
INSERT INTO public.industries (code, name, lexicon, tensions, taboos) VALUES ('emprendimiento', 'Emprendimiento', '["socio", "cliente", "caja", "idea", "validar", "facturar", "renunciar", "negocio"]', '["renunciar al empleo para emprender", "trabajar más que cuando eras empleado", "el socio que no aporta", "vender antes de construir"]', '["''sé tu propio jefe'' romántico", "ingresos pasivos fáciles", "historias de éxito sin contexto"]');
INSERT INTO public.industries (code, name, lexicon, tensions, taboos) VALUES ('consultoria', 'Consultoría', '["diagnóstico", "propuesta", "honorarios", "entregable", "cliente", "proyecto", "junta directiva"]', '["vender horas vs. resultados", "el informe que nadie lee", "el cliente que pide solución sin aceptar el diagnóstico", "competir por precio"]', '["''soluciones integrales''", "''acompañamiento'' vacío", "jerga de PowerPoint"]');
INSERT INTO public.industries (code, name, lexicon, tensions, taboos) VALUES ('servicios_profesionales', 'Servicios profesionales', '["cliente", "cotización", "tarifa", "referido", "agenda", "proyecto"]', '["cobrar poco por miedo a perder clientes", "el cliente que pide rebaja", "trabajar por referidos sin sistema"]', '["''calidad y compromiso''", "''excelencia'' como argumento"]');
INSERT INTO public.industries (code, name, lexicon, tensions, taboos) VALUES ('derecho', 'Derecho', '["contrato", "demanda", "abogado", "cláusula", "firma", "proceso", "liquidación"]', '["firmar sin leer", "llamar al abogado cuando ya hay problema", "el contrato copiado de internet"]', '["asesoría legal específica sin caso", "interpretaciones categóricas sin norma", "miedo legal exagerado"]');
INSERT INTO public.industries (code, name, lexicon, tensions, taboos) VALUES ('real_estate', 'Real Estate', '["arriendo", "cuota inicial", "crédito hipotecario", "valorización", "metro cuadrado", "inmueble"]', '["arrendar vs. comprar", "comprar sobre planos", "la ''inversión segura'' que no lo es"]', '["valorización garantizada", "urgencia falsa (''últimas unidades'')"]');
INSERT INTO public.industries (code, name, lexicon, tensions, taboos) VALUES ('retail', 'Retail', '["tienda", "vitrina", "inventario", "cliente", "descuento", "rotación de producto", "caja"]', '["el cliente que mira y compra en línea", "descuentos que destruyen margen", "inventario quieto"]', '["''calidad al mejor precio''"]');
INSERT INTO public.industries (code, name, lexicon, tensions, taboos) VALUES ('gastronomia', 'Gastronomía', '["carta", "plato", "cocina", "domicilio", "mesa", "receta", "costo del plato"]', '["restaurante lleno y sin utilidad", "las apps de domicilio que se comen el margen", "la receta de la abuela vs. el negocio"]', '["''sabor único''", "''hecho con amor'' genérico"]');
INSERT INTO public.industries (code, name, lexicon, tensions, taboos) VALUES ('industria', 'Industria / manufactura', '["planta", "operario", "turno", "producción", "calidad", "seguridad industrial", "mantenimiento"]', '["producir más vs. accidentes", "el mantenimiento que se aplaza", "la experiencia del operario que nadie documenta"]', '["''industria 4.0'' vacío", "cifras de productividad sin fuente"]');
INSERT INTO public.industries (code, name, lexicon, tensions, taboos) VALUES ('turismo', 'Turismo', '["viaje", "destino", "temporada", "reserva", "hotel", "plan", "vacaciones"]', '["viajar para la foto vs. para vivirlo", "temporada alta y precios", "destinos saturados"]', '["''paraíso escondido''", "precios engañosos"]');
INSERT INTO public.industries (code, name, lexicon, tensions, taboos) VALUES ('maternidad', 'Maternidad', '["hijos", "crianza", "culpa", "pareja", "colegio", "tareas", "tiempo", "rutina"]', '["la madre que trabaja y siente que no llega a todo", "la carga mental invisible", "tiempo de calidad vs. cantidad", "comparación con otras mamás"]', '["juzgar a las madres", "''la madre perfecta''", "prometer hijos felices con un truco"]');
