INSERT INTO public.mechanisms (code, name, description, foundation, source, confidence, caveat) VALUES ('curiosidad', 'Curiosidad', 'Abre una brecha entre lo que el lector sabe y lo que quiere saber.', 'Teoría de la brecha de información.', 'Loewenstein, G. (1994). The psychology of curiosity. Psychological Bulletin, 116(1).', 'alta', 'Si la brecha es enorme u obvia, no activa nada. Si el contenido no la cierra, quema confianza.');
INSERT INTO public.mechanisms (code, name, description, foundation, source, confidence, caveat) VALUES ('contradiccion', 'Contradicción', 'Choca con una creencia que el lector da por cierta.', 'Variables colativas: incongruencia y sorpresa generan exploración.', 'Berlyne, D. (1960). Conflict, Arousal and Curiosity.', 'alta', 'Necesita resolverse con un argumento defendible; si no, es solo ruido.');
INSERT INTO public.mechanisms (code, name, description, foundation, source, confidence, caveat) VALUES ('identificacion', 'Identificación', 'El lector se reconoce en una situación concreta.', 'Efecto de autorreferencia: procesamos mejor lo que nos involucra.', 'Rogers, Kuiper & Kirker (1977). JPSP, 35(9).', 'alta', 'Lo genérico (''a todos nos pasa'') no identifica; lo específico sí.');
INSERT INTO public.mechanisms (code, name, description, foundation, source, confidence, caveat) VALUES ('humor', 'Humor', 'Una violación benigna de lo esperado.', 'Teoría de la violación benigna.', 'McGraw & Warren (2010). Psychological Science, 21(8).', 'media', 'El umbral entre benigno y ofensivo depende de la audiencia y la cultura.');
INSERT INTO public.mechanisms (code, name, description, foundation, source, confidence, caveat) VALUES ('satira', 'Sátira', 'Exagera una práctica del sector para exponer lo absurda que es.', 'Subtipo de humor (violación benigna) con un blanco crítico.', 'McGraw & Warren (2010).', 'media', 'El blanco es la práctica, nunca una persona identificable.');
INSERT INTO public.mechanisms (code, name, description, foundation, source, confidence, caveat) VALUES ('ironia', 'Ironía', 'Dice lo contrario de lo que quiere decir y confía en que el lector lo note.', 'Incongruencia resuelta por el lector: la complicidad aumenta el vínculo.', 'Berlyne (1960); McGraw & Warren (2010).', 'media', 'Por escrito se pierde fácilmente; necesita pistas claras.');
INSERT INTO public.mechanisms (code, name, description, foundation, source, confidence, caveat) VALUES ('controversia', 'Controversia', 'Toma una posición con la que una parte de la audiencia no estará de acuerdo.', 'Emociones de alta activación (indignación) se asocian a más difusión.', 'Berger & Milkman (2012). What makes online content viral? JMR, 49(2).', 'media', 'Correlacional. Atrae comentarios, no necesariamente clientes. Requiere fundamento.');
INSERT INTO public.mechanisms (code, name, description, foundation, source, confidence, caveat) VALUES ('miedo_perder', 'Miedo a perder', 'Hace visible lo que el lector está perdiendo hoy.', 'Aversión a la pérdida.', 'Kahneman & Tversky (1979). Prospect theory. Econometrica, 47(2).', 'alta', 'Si se abusa, se percibe como manipulación.');
INSERT INTO public.mechanisms (code, name, description, foundation, source, confidence, caveat) VALUES ('advertencia', 'Advertencia', 'Señala un riesgo concreto antes de que ocurra.', 'Aversión a la pérdida + valor práctico.', 'Kahneman & Tversky (1979); Berger (2013), Contagious.', 'media', 'Debe ser un riesgo real y proporcional, no alarmismo.');
INSERT INTO public.mechanisms (code, name, description, foundation, source, confidence, caveat) VALUES ('revelacion', 'Revelación', 'Muestra lo que hay detrás de algo que todos ven.', 'Brecha de información + recompensa por insight.', 'Loewenstein (1994).', 'media', 'La revelación tiene que ser genuinamente no obvia para esa audiencia.');
INSERT INTO public.mechanisms (code, name, description, foundation, source, confidence, caveat) VALUES ('confesion', 'Confesión', 'Admite un error o debilidad propia.', 'Efecto pratfall: en alguien competente, un error aumenta la simpatía.', 'Aronson, Willerman & Floyd (1966). Psychonomic Science, 4.', 'media', 'Funciona si ya existe competencia percibida. Sin ella, resta autoridad.');
INSERT INTO public.mechanisms (code, name, description, foundation, source, confidence, caveat) VALUES ('aspiracion', 'Aspiración', 'Muestra un estado deseado alcanzable.', 'Motivación por metas y autoimagen ideal.', 'Cialdini (2021), Influence; Berger (2013).', 'media', 'La promesa debe ser creíble; si no, suena a gurú.');
INSERT INTO public.mechanisms (code, name, description, foundation, source, confidence, caveat) VALUES ('intriga', 'Intriga narrativa', 'Empieza una historia sin resolverla.', 'Transporte narrativo + bucle abierto.', 'Green & Brock (2000). JPSP, 79(5). (El efecto Zeigarnik tiene evidencia débil: es solo una heurística.)', 'media', 'La historia debe pagarse: si el final decepciona, el lector no vuelve.');
INSERT INTO public.mechanisms (code, name, description, foundation, source, confidence, caveat) VALUES ('storytelling', 'Storytelling', 'Una escena con personaje, conflicto y detalle concreto.', 'El transporte narrativo reduce la contraargumentación.', 'Green & Brock (2000).', 'alta', 'Sin conflicto no hay historia: es solo un relato.');
INSERT INTO public.mechanisms (code, name, description, foundation, source, confidence, caveat) VALUES ('autoridad', 'Autoridad', 'Habla desde la experiencia o el criterio demostrable.', 'Principio de autoridad.', 'Cialdini (2021), Influence: New and Expanded.', 'media', 'La autoridad se muestra con criterio, no con títulos. La falsa autoridad es un riesgo reputacional.');
INSERT INTO public.mechanisms (code, name, description, foundation, source, confidence, caveat) VALUES ('especificidad', 'Especificidad', 'Detalles concretos (cifra real, lugar, objeto, fecha) que vuelven creíble el mensaje.', 'Lo concreto se entiende y se recuerda mejor.', 'Heath & Heath (2007). Made to Stick.', 'media', 'Prohibido inventar cifras. Si no hay dato real, se usa un detalle de escena.');
INSERT INTO public.mechanisms (code, name, description, foundation, source, confidence, caveat) VALUES ('prueba_social', 'Prueba social', 'Lo que hacen o piensan otros como uno.', 'Principio de prueba social.', 'Cialdini (2021).', 'media', 'Sin datos reales no se afirma ''la mayoría''.');
INSERT INTO public.mechanisms (code, name, description, foundation, source, confidence, caveat) VALUES ('valor_practico', 'Valor práctico', 'Algo útil que se puede aplicar hoy.', 'STEPPS: el valor práctico se comparte para ayudar a otros.', 'Berger (2013), Contagious.', 'media', 'Lo útil y genérico no engancha; lo útil y específico sí.');
INSERT INTO public.mechanisms (code, name, description, foundation, source, confidence, caveat) VALUES ('moneda_social', 'Moneda social', 'Compartirlo hace ver bien a quien lo comparte (inteligente, enterado).', 'STEPPS: social currency.', 'Berger (2013), Contagious.', 'media', '—');
INSERT INTO public.mechanisms (code, name, description, foundation, source, confidence, caveat) VALUES ('pertenencia', 'Pertenencia', 'Habla a ''los que somos X''.', 'Principio de unidad / identidad compartida.', 'Cialdini (2021), capítulo ''Unity''.', 'media', 'Puede excluir a audiencias que también importan.');
INSERT INTO public.mechanisms (code, name, description, foundation, source, confidence, caveat) VALUES ('enemigo_comun', 'Enemigo común', 'Une al lector contra una práctica, mito o sistema (no contra una persona).', 'Identidad de grupo frente a un exogrupo; indignación de alta activación.', 'Berger & Milkman (2012); Cialdini (2021).', 'baja', 'El enemigo es una práctica. Atacar personas o grupos destruye la marca.');
INSERT INTO public.mechanisms (code, name, description, foundation, source, confidence, caveat) VALUES ('sorpresa', 'Sorpresa', 'Un giro o dato que el lector no anticipaba.', 'Variables colativas (novedad/sorpresa).', 'Berlyne (1960).', 'alta', 'La sorpresa sin relevancia se olvida.');
INSERT INTO public.mechanisms (code, name, description, foundation, source, confidence, caveat) VALUES ('comparacion', 'Comparación', 'Pone dos opciones, personas o momentos lado a lado.', 'El contraste facilita el juicio y hace visible la diferencia.', 'Heath & Heath (2007); práctica de copywriting.', 'media', 'Comparaciones injustas se perciben como manipulación.');

INSERT INTO public.observed_hooks (id, creator_id, platform, published_at, text, url, mechanisms, structure_code, construction, evidence, confidence, is_counter_example) VALUES (1, 11, 'X', '2025-05-27', '¿Quieres saber por qué hay millonarios que no impresionan a nadie… y hippies sin un duro que lideran multitudes? El estatus no es lo que tú crees. Y jugarlo mal te puede arruinar la vida.', 'https://x.com/TechEuge/status/1927436143437775315', '["contradiccion", "curiosidad", "miedo_perder"]', 'CON-07', 'Dos extremos que rompen la regla → corrección de creencia → consecuencia personal.', 'O', 'media', false);
INSERT INTO public.observed_hooks (id, creator_id, platform, published_at, text, url, mechanisms, structure_code, construction, evidence, confidence, is_counter_example) VALUES (2, 11, 'X', '2025-05-16', 'Los mejores pensadores no repiten eslóganes. Pueden defender la idea opuesta mejor que sus rivales. Y luego desmontarla.', 'https://x.com/TechEuge/status/1923338117018239061', '["aspiracion", "contradiccion"]', 'CON-06', 'Define a un grupo admirado por lo que no hace y luego por una conducta concreta.', 'O', 'media', false);
INSERT INTO public.observed_hooks (id, creator_id, platform, published_at, text, url, mechanisms, structure_code, construction, evidence, confidence, is_counter_example) VALUES (3, 11, 'X', '2024-07-22', 'En enero de este año decidí hacer un experimento: Quería comprobar si podía monetizar un hobby sin usar mi marca personal. En poco tiempo conseguí generar $1.000…', 'https://x.com/TechEuge/status/1815303655165194491', '["intriga", "especificidad", "curiosidad"]', 'TRA-03', 'Fecha + reto con restricción autoimpuesta + resultado concreto.', 'O', 'media', false);
INSERT INTO public.observed_hooks (id, creator_id, platform, published_at, text, url, mechanisms, structure_code, construction, evidence, confidence, is_counter_example) VALUES (4, 11, 'X', '2024-07-06', 'El conocimiento sin motivación no entra.', 'https://x.com/TechEuge/status/1809647637240639498', '["contradiccion"]', NULL, 'Aforismo corto con verbo coloquial.', 'O', 'media', false);
INSERT INTO public.observed_hooks (id, creator_id, platform, published_at, text, url, mechanisms, structure_code, construction, evidence, confidence, is_counter_example) VALUES (5, 11, 'X', '2025-08-24', '¿Era más fácil emprender antes… o lo es ahora?', 'https://x.com/TechEuge/status/1959617967060029943', '["controversia", "identificacion"]', 'POL-10', 'Dilema de dos verdades: busca comentarios.', 'O', 'media', false);
INSERT INTO public.observed_hooks (id, creator_id, platform, published_at, text, url, mechanisms, structure_code, construction, evidence, confidence, is_counter_example) VALUES (6, 14, 'LinkedIn', '2021-11-01', 'Una empresa quería vender más relojes. Para esto, contrató un famoso…', 'https://www.linkedin.com/posts/jurgenklaric-neurociencias_una-empresa-quería-vender-más-relojes-para-activity-6860924336220487680-ZCst', '["intriga", "storytelling"]', 'ESC-02', 'Caso ajeno in medias res; decisión que intuimos errada.', 'O', 'media', false);
INSERT INTO public.observed_hooks (id, creator_id, platform, published_at, text, url, mechanisms, structure_code, construction, evidence, confidence, is_counter_example) VALUES (7, 14, 'LinkedIn', '2021-10-12', 'He sido vendedor desde que era niño. Por algo me llamaban “El niño…', 'https://www.linkedin.com/posts/jurgenklaric-neurociencias_he-sido-vendedor-desde-que-era-ni%C3%B1o-por-activity-6853676419545907200-vfS5', '["curiosidad", "storytelling"]', 'ESC-05', 'Apodo cortado antes del ''ver más''.', 'O', 'media', false);
INSERT INTO public.observed_hooks (id, creator_id, platform, published_at, text, url, mechanisms, structure_code, construction, evidence, confidence, is_counter_example) VALUES (8, 14, 'LinkedIn', '2021-11-03', '¿Qué pasaría si perdieras el miedo a vender?', 'https://www.linkedin.com/posts/jurgenklaric-neurociencias_qu%C3%A9-pasar%C3%ADa-si-perdieras-el-miedo-a-vender-activity-6861650958531784704-tvG8', '["aspiracion"]', NULL, 'Hipotético que nombra un miedo concreto.', 'O', 'media', false);
INSERT INTO public.observed_hooks (id, creator_id, platform, published_at, text, url, mechanisms, structure_code, construction, evidence, confidence, is_counter_example) VALUES (9, 14, 'LinkedIn', '2019-11-25', 'La verdad es que Latinoamérica está pasando por un periodo económico y…', 'https://www.linkedin.com/posts/jurgenklaric-neurociencias_la-verdad-es-que-latinoam%C3%A9rica-esta-pasando-activity-6604748881513205760-I4uF', '["autoridad"]', NULL, 'Muletilla oral de franqueza.', 'O', 'media', false);
INSERT INTO public.observed_hooks (id, creator_id, platform, published_at, text, url, mechanisms, structure_code, construction, evidence, confidence, is_counter_example) VALUES (10, 14, 'LinkedIn', '2022-08-30', 'El Marketing Digital es mucho más sencillo de lo que la mayoría de la…', 'https://es.linkedin.com/posts/jurgenklaric-neurociencias_el-marketing-digital-es-mucho-m%C3%A1s-sencillo-activity-6970391752222351361-bVTd', '["contradiccion"]', NULL, 'Minimiza la complejidad y crea un exogrupo (''la mayoría'').', 'O', 'media', false);
INSERT INTO public.observed_hooks (id, creator_id, platform, published_at, text, url, mechanisms, structure_code, construction, evidence, confidence, is_counter_example) VALUES (11, 10, 'LinkedIn', '2023-09-02', 'El 1 de septiembre de 2015, estaba entrando a Miami, Estados Unidos, con…', 'https://es.linkedin.com/posts/vilmanunezvillanueva_el-1-de-septiembre-de-2015-estaba-entrando-activity-7103791501922422784-orAi', '["storytelling", "especificidad"]', 'ESC-01', 'Fecha exacta + lugar + acción en curso.', 'O', 'media', false);
