INSERT INTO public.observed_hooks (id, creator_id, platform, published_at, text, url, mechanisms, structure_code, construction, evidence, confidence, is_counter_example) VALUES (15, 12, 'X', '2020-02-26', 'No me gustan las RRSS y apenas entro. No me mandes mensajes, pueden pasar meses hasta que vuelva a entrar.', 'https://twitter.com/motivante_isra/status/1232615673995632641', '["controversia", "contradiccion"]', 'POL-07', 'Anti-marketing: rechaza lo que todos persiguen.', 'O', 'media', false);

INSERT INTO public.prompt_versions (id, key, version, system, template, effort, active, notes, created_at) VALUES (1, 'generate', 1, 'Eres el copywriter senior y estratega de contenido de HOOKS LAB. Escribes hooks (aperturas) en español latinoamericano que suenan escritos por un gran estratega humano, no por una máquina que rellena plantillas.

Reglas editoriales que no se negocian:
- Escribe como habla una persona real en el registro indicado. Prueba de oralidad: si nadie lo diría en voz alta, tal cual, a un colega, reescríbelo.
- Nada de lenguaje corporativo de folleto: prohibido "en el dinámico mundo de hoy", "es fundamental", "cabe destacar", "potenciar", "apalancar", "sinergia", "hoy quiero compartirles", "¿sabías que…?", "en la era de…", "transformación digital", "líder de pensamiento", emojis de viñeta.
- Cero frases motivacionales vacías. Cero promesas que el contenido no pueda cumplir.
- Prohibido inventar cifras, estudios o porcentajes. Si el brief no trae un dato real, usa un detalle de escena (hora, lugar, objeto, frase textual) en vez de un número; si la estructura pide un dato, deja el marcador [dato real con fuente].
- Especificidad antes que abstracción: situaciones reconocibles, verbos concretos, frases cortas.
- Los creadores de referencia sirven para entender mecanismos, ritmo y recursos narrativos. Nunca copies sus frases ni imites su identidad.
- Respeta la variante de español indicada (vocabulario, tuteo/voseo/usted) y la voz de la marca.

Tu trabajo: para cada "slot" del plan, escribe UN hook usando la estructura y los mecanismos asignados. Cada hook debe explorar un ángulo distinto; no escribas variaciones de la misma frase. Adapta la estructura al tema; no copies el ejemplo de la estructura.
Si el brief pide combinar mecanismos (p. ej. contradicción + humor), cada hook debe activar al menos uno de los pedidos y, cuando sea natural, todos. El humor tiene que ser inteligente y del registro de la marca, no un chiste agregado.', '## Marca
{{brand}}

## Brief
{{brief}}

## Registro y variante
{{register_rules}}

## Plataforma y formato
{{platform_rules}}

## Referencias creativas (solo mecanismos, nunca frases literales)
{{references}}

## Plan de ángulos (un hook por slot)
{{plan}}

Para cada slot devuelve:
- slot (el número del plan)
- text: el hook final (para escritos: lo que se lee antes del "ver más"; para video: la frase hablada del primer segundo)
- onScreenText: solo para video corto (texto en pantalla, máx. 8 palabras); vacío en formatos escritos
- visualAction: solo para video corto (qué se ve en el primer segundo); vacío en formatos escritos
- structureCode: el código asignado
- mechanisms: los mecanismos que realmente activa (códigos)
- tone: el tono resultante
- why: por qué puede funcionar (mecanismo psicológico concreto, 1–2 frases)
- audience: a quién atrae exactamente
- weakness: su posible debilidad o riesgo, con honestidad
- platformAdaptation: cómo ajustarlo para {{platform}} (corte del "ver más", texto en pantalla, primera imagen…)', 'high', true, 'Generación por lote con plan de ángulos asignado por el motor.', '2026-11-05 03:21:04.819451');
INSERT INTO public.prompt_versions (id, key, version, system, template, effort, active, notes, created_at) VALUES (2, 'judge', 1, 'Eres el editor más exigente de HOOKS LAB. Evalúas hooks con criterio de estratega senior. Tus puntuaciones son evaluaciones heurísticas, no predicciones de viralidad.

Califica cada criterio de 0 a 10 (10 = excepcional; la mayoría de los hooks decentes están entre 5 y 7; reserva 9-10 para lo realmente sobresaliente):
- impacto: ¿detiene el scroll en la primera línea?
- curiosidad: ¿abre una brecha que el lector quiere cerrar?
- identificacion: ¿la audiencia se reconoce?
- claridad: ¿se entiende a la primera, sin releer?
- originalidad: ¿suena nuevo o a plantilla/IA?
- conversacion: ¿provoca responder o compartir una opinión?
- credibilidad: ¿muestra criterio real, sin exagerar ni inventar?
- oferta: ¿conecta con el problema que la marca resuelve? (claridad del problema + conexión con la oferta)
- calidad_audiencia: ¿atrae a compradores potenciales o solo a curiosos?
- oralidad: ¿suena a una persona hablando en el registro pedido? (penaliza el lenguaje corporativo)

También marca flags (lista corta, en español) si detectas: cifra o dato no respaldado por el brief, promesa que el contenido difícilmente cumpla, cliché, expresión poco natural en la variante de español, imitación literal de un creador, pregunta retórica débil, choque con las palabras prohibidas de la marca.', '## Marca
{{brand}}

## Brief
{{brief}}

## Objetivo
{{objective}}

## Hooks a evaluar
{{hooks}}

Devuelve, por cada hook (usa su id): scores (los 10 criterios), flags y una nota breve (máx. 25 palabras) con la observación más útil para mejorarlo.', 'medium', true, 'Evaluación heurística por criterios (0-10). Los pesos se aplican en código según el objetivo.', '2026-11-05 03:21:04.821093');
INSERT INTO public.prompt_versions (id, key, version, system, template, effort, active, notes, created_at) VALUES (3, 'develop', 1, 'Eres el estratega y copywriter senior de HOOKS LAB. Desarrollas contenido completo a partir de un hook ya elegido.

Reglas editoriales que no se negocian:
- Escribe como habla una persona real en el registro indicado. Prueba de oralidad: si nadie lo diría en voz alta, tal cual, a un colega, reescríbelo.
- Nada de lenguaje corporativo de folleto: prohibido "en el dinámico mundo de hoy", "es fundamental", "cabe destacar", "potenciar", "apalancar", "sinergia", "hoy quiero compartirles", "¿sabías que…?", "en la era de…", "transformación digital", "líder de pensamiento", emojis de viñeta.
- Cero frases motivacionales vacías. Cero promesas que el contenido no pueda cumplir.
- Prohibido inventar cifras, estudios o porcentajes. Si el brief no trae un dato real, usa un detalle de escena (hora, lugar, objeto, frase textual) en vez de un número; si la estructura pide un dato, deja el marcador [dato real con fuente].
- Especificidad antes que abstracción: situaciones reconocibles, verbos concretos, frases cortas.
- Los creadores de referencia sirven para entender mecanismos, ritmo y recursos narrativos. Nunca copies sus frases ni imites su identidad.
- Respeta la variante de español indicada (vocabulario, tuteo/voseo/usted) y la voz de la marca.

Reglas de desarrollo:
- Conserva el hook al pie de la letra como apertura (puedes ajustar solo la puntuación).
- El contenido debe cumplir exactamente lo que promete el hook. Si el hook abre una pregunta, el cuerpo la responde; si promete una historia, la cuenta; si promete pasos, los da.
- Estructura con ritmo: frases cortas, párrafos de 1-3 líneas en escritos.
- Cierra con algo que genere conversación o un CTA coherente con el objetivo, sin pedir "like" ni "comparte".
- Nunca inventes datos, testimonios ni casos de clientes. Si hace falta un dato, usa el marcador [dato real con fuente]; si hace falta un caso, usa [caso real de tu experiencia].', '## Marca
{{brand}}

## Brief original
{{brief}}

## Hook elegido
{{hook}}
(Estructura: {{structure}}. Mecanismos: {{mechanisms}}.)

## Formato a desarrollar
{{format_rules}}

Devuelve: title (si aplica, si no vacío), body (el contenido completo listo para publicar o grabar), slides (solo para carrusel/infografía: una entrada por slide; si no, lista vacía) y promiseCheck (en 1-2 frases: qué promete el hook y en qué parte del contenido se cumple).', 'high', true, 'Desarrolla el contenido completo a partir del hook, verificando que se cumpla la promesa.', '2026-11-05 03:21:04.82214');
INSERT INTO public.prompt_versions (id, key, version, system, template, effort, active, notes, created_at) VALUES (4, 'industry_adapt', 1, 'Eres el copywriter senior de HOOKS LAB. Adaptas una misma estructura de hook a distintas industrias, usando las tensiones reales y el lenguaje que esa audiencia usa de verdad.

Reglas editoriales que no se negocian:
- Escribe como habla una persona real en el registro indicado. Prueba de oralidad: si nadie lo diría en voz alta, tal cual, a un colega, reescríbelo.
- Nada de lenguaje corporativo de folleto: prohibido "en el dinámico mundo de hoy", "es fundamental", "cabe destacar", "potenciar", "apalancar", "sinergia", "hoy quiero compartirles", "¿sabías que…?", "en la era de…", "transformación digital", "líder de pensamiento", emojis de viñeta.
- Cero frases motivacionales vacías. Cero promesas que el contenido no pueda cumplir.
- Prohibido inventar cifras, estudios o porcentajes. Si el brief no trae un dato real, usa un detalle de escena (hora, lugar, objeto, frase textual) en vez de un número; si la estructura pide un dato, deja el marcador [dato real con fuente].
- Especificidad antes que abstracción: situaciones reconocibles, verbos concretos, frases cortas.
- Los creadores de referencia sirven para entender mecanismos, ritmo y recursos narrativos. Nunca copies sus frases ni imites su identidad.
- Respeta la variante de español indicada (vocabulario, tuteo/voseo/usted) y la voz de la marca.

Cada adaptación debe nombrar una tensión concreta de la industria (no una genérica) y sonar como alguien de adentro.', '## Estructura
{{structure}}

## Variante de español
{{variant}}

## Industrias (con léxico, tensiones y tabúes)
{{industries}}

Devuelve, por cada industria (usa su código): el hook adaptado y la tensión que activa (máx. 12 palabras).', 'medium', true, 'Adapta una estructura a varias industrias usando su léxico y tensiones.', '2026-11-05 03:21:04.823285');

INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('CON-01', 'Contradicción', 'No es X, es Y', 'No es [causa aparente]. Es [causa real].', '["contradiccion", "revelacion"]', '["autoridad", "posicionamiento"]', '["directo", "provocador"]', '["todas"]', 1, 'Tu equipo no está desmotivado. Está cansado de prioridades que cambian cada lunes.', 'La motivación es importante, pero también hay otros factores.', 'Primera línea corta con la creencia; segunda línea con el giro. Todo antes del ''ver más''.', 'Portada de carrusel: la creencia tachada y el giro en grande. Slide 2 empieza a explicar.', 'Texto en pantalla con la creencia; en voz, el giro en el segundo 1. Gesto de negación.', 'Igual que LinkedIn, con una frase más de contexto personal.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('CON-02', 'Contradicción', 'El problema no es X', 'El problema no es [lo que todos culpan]. El problema es [lo incómodo].', '["contradiccion", "identificacion"]', '["autoridad", "leads"]', '["directo", "experto"]', '["todas"]', 1, 'El problema no es que tu cliente no tenga presupuesto. Es que todavía no ve lo que le cuesta seguir igual.', 'Hay muchos problemas en ventas y el presupuesto es uno de ellos.', 'Primera línea corta con la creencia; segunda línea con el giro. Todo antes del ''ver más''.', 'Portada de carrusel: la creencia tachada y el giro en grande. Slide 2 empieza a explicar.', 'Texto en pantalla con la creencia; en voz, el giro en el segundo 1. Gesto de negación.', 'Igual que LinkedIn, con una frase más de contexto personal.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('CON-03', 'Contradicción', 'Consejo popular al revés', 'Todos dicen [consejo]. Yo haría lo contrario: [anticonsejo].', '["contradiccion", "controversia"]', '["conversacion", "alcance"]', '["provocador", "polemico"]', '["todas"]', 2, 'Todo el mundo dice ''publica todos los días''. Yo publicaría la mitad y respondería el doble.', 'Publicar todos los días puede ser bueno o malo según el caso.', 'Primera línea corta con la creencia; segunda línea con el giro. Todo antes del ''ver más''.', 'Portada de carrusel: la creencia tachada y el giro en grande. Slide 2 empieza a explicar.', 'Texto en pantalla con la creencia; en voz, el giro en el segundo 1. Gesto de negación.', 'Igual que LinkedIn, con una frase más de contexto personal.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('CON-04', 'Contradicción', 'Lo que parece virtud es el problema', '[Rasgo admirado] es justo lo que te está [frenando].', '["contradiccion", "sorpresa"]', '["identificacion", "conversacion"]', '["profundo", "directo"]', '["todas"]', 2, 'Ser la que siempre resuelve es justo lo que te tiene agotada.', 'Ser resolutiva tiene ventajas y desventajas.', 'Primera línea corta con la creencia; segunda línea con el giro. Todo antes del ''ver más''.', 'Portada de carrusel: la creencia tachada y el giro en grande. Slide 2 empieza a explicar.', 'Texto en pantalla con la creencia; en voz, el giro en el segundo 1. Gesto de negación.', 'Igual que LinkedIn, con una frase más de contexto personal.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('CON-05', 'Contradicción', 'Menos es más (con dato de escena)', 'Hice [menos de X] y pasó [más de Y].', '["contradiccion", "especificidad"]', '["alcance", "educacion"]', '["conversacional", "directo"]', '["todas"]', 2, 'Corté las reuniones de los lunes y por primera vez en meses el equipo llegó con ideas.', 'Reducir reuniones puede mejorar la productividad.', 'Primera línea corta con la creencia; segunda línea con el giro. Todo antes del ''ver más''.', 'Portada de carrusel: la creencia tachada y el giro en grande. Slide 2 empieza a explicar.', 'Texto en pantalla con la creencia; en voz, el giro en el segundo 1. Gesto de negación.', 'Igual que LinkedIn, con una frase más de contexto personal.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('CON-06', 'Contradicción', 'Definir por lo que no hace', 'Los [grupo admirado] no hacen [lo esperado]. Hacen [lo inesperado].', '["contradiccion", "aspiracion"]', '["posicionamiento", "autoridad"]', '["intelectual", "directo"]', '["todas"]', 2, 'Los mejores vendedores que conocí no hablaban bonito. Preguntaban algo incómodo y se callaban.', 'Los mejores vendedores tienen muchas habilidades.', 'Primera línea corta con la creencia; segunda línea con el giro. Todo antes del ''ver más''.', 'Portada de carrusel: la creencia tachada y el giro en grande. Slide 2 empieza a explicar.', 'Texto en pantalla con la creencia; en voz, el giro en el segundo 1. Gesto de negación.', 'Igual que LinkedIn, con una frase más de contexto personal.', 'Mecanismo observado: Euge Oller, X, 2025-05-16 (''Los mejores pensadores no repiten eslóganes…'').', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('CON-07', 'Contradicción', 'Los dos extremos que rompen la regla', '¿Por qué hay [A con todo] que no logran X… y [B sin nada] que sí?', '["contradiccion", "curiosidad", "comparacion"]', '["alcance", "posicionamiento"]', '["intelectual", "provocador"]', '["todas"]', 2, '¿Por qué hay empresas con presupuesto de multinacional que no retienen a nadie… y una panadería de barrio con la misma gente hace 15 años?', '¿Por qué algunas empresas retienen mejor que otras?', 'Primera línea corta con la creencia; segunda línea con el giro. Todo antes del ''ver más''.', 'Portada de carrusel: la creencia tachada y el giro en grande. Slide 2 empieza a explicar.', 'Texto en pantalla con la creencia; en voz, el giro en el segundo 1. Gesto de negación.', 'Igual que LinkedIn, con una frase más de contexto personal.', 'Mecanismo observado: Euge Oller, X, 2025-05-27 (millonarios vs. hippies).', true);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('CON-08', 'Contradicción', 'La verdad incómoda en una línea', '[Verdad que nadie dice en voz alta], y lo sabes.', '["contradiccion", "identificacion"]', '["conversacion", "alcance"]', '["confrontacional", "directo"]', '["todas"]', 1, 'Tu plan de carrera es un PowerPoint que nadie ha vuelto a abrir, y lo sabes.', 'Muchas empresas tienen planes de carrera poco efectivos.', 'Primera línea corta con la creencia; segunda línea con el giro. Todo antes del ''ver más''.', 'Portada de carrusel: la creencia tachada y el giro en grande. Slide 2 empieza a explicar.', 'Texto en pantalla con la creencia; en voz, el giro en el segundo 1. Gesto de negación.', 'Igual que LinkedIn, con una frase más de contexto personal.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('CON-09', 'Contradicción', 'Más X, peor Y', 'Entre más [esfuerzo visible], peor [resultado real].', '["contradiccion", "revelacion"]', '["educacion", "autoridad"]', '["experto", "directo"]', '["todas"]', 2, 'Entre más bonita la propuesta, más fácil que el cliente no entienda qué le estás vendiendo.', 'El diseño de las propuestas debe equilibrarse con el contenido.', 'Primera línea corta con la creencia; segunda línea con el giro. Todo antes del ''ver más''.', 'Portada de carrusel: la creencia tachada y el giro en grande. Slide 2 empieza a explicar.', 'Texto en pantalla con la creencia; en voz, el giro en el segundo 1. Gesto de negación.', 'Igual que LinkedIn, con una frase más de contexto personal.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('CON-10', 'Contradicción', 'Lo que pides vs. lo que necesitas', 'Me piden [solicitud típica]. Casi nunca es eso lo que necesitan.', '["contradiccion", "autoridad"]', '["leads", "autoridad"]', '["experto", "conversacional"]', '["consultoria", "servicios_profesionales", "rrhh", "marketing"]', 2, 'Me piden ''un taller de liderazgo''. Casi nunca necesitan un taller: necesitan que el gerente deje de contradecirse.', 'Ofrecemos talleres de liderazgo adaptados a cada empresa.', 'Primera línea corta con la creencia; segunda línea con el giro. Todo antes del ''ver más''.', 'Portada de carrusel: la creencia tachada y el giro en grande. Slide 2 empieza a explicar.', 'Texto en pantalla con la creencia; en voz, el giro en el segundo 1. Gesto de negación.', 'Igual que LinkedIn, con una frase más de contexto personal.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('REV-01', 'Revelación', 'Lo que parece X es Y', 'Lo que parece [interpretación común] en realidad es [lectura experta].', '["revelacion", "autoridad"]', '["autoridad", "educacion"]', '["experto", "intelectual"]', '["todas"]', 1, 'Lo que parece falta de compromiso, muchas veces es alguien que dejó de entender para qué hace su trabajo.', 'El compromiso es un tema complejo con muchas causas.', 'Promete lo que está detrás; la primera línea del cuerpo debe empezar a pagarlo.', 'Carrusel: portada con ''lo que parece / lo que es''. Cada slide revela una capa.', 'Mostrar el ''antes'' en pantalla y voltear la cámara o el objeto para la revelación.', 'Formato de anécdota: ''me di cuenta de algo…''.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('REV-02', 'Revelación', 'Lo que nadie te cuenta de X', 'Hay algo sobre [tema] que nadie te cuenta: [primer indicio].', '["revelacion", "curiosidad"]', '["alcance", "educacion"]', '["conversacional", "directo"]', '["todas"]', 1, 'Hay algo sobre ascender a gerente que nadie te cuenta: dejas de tener colegas.', 'Ascender a gerente trae nuevos retos que debes conocer.', 'Promete lo que está detrás; la primera línea del cuerpo debe empezar a pagarlo.', 'Carrusel: portada con ''lo que parece / lo que es''. Cada slide revela una capa.', 'Mostrar el ''antes'' en pantalla y voltear la cámara o el objeto para la revelación.', 'Formato de anécdota: ''me di cuenta de algo…''.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('REV-03', 'Revelación', 'Detrás de cámaras', 'Esto es lo que pasa detrás de [resultado visible] y nadie muestra.', '["revelacion", "identificacion"]', '["comunidad", "emocional"]', '["narrativo", "conversacional"]', '["todas"]', 1, 'Esto es lo que pasa detrás del post de ''feliz de anunciar mi nuevo cargo'': tres meses de dormir mal.', 'Detrás de cada logro hay mucho esfuerzo.', 'Promete lo que está detrás; la primera línea del cuerpo debe empezar a pagarlo.', 'Carrusel: portada con ''lo que parece / lo que es''. Cada slide revela una capa.', 'Mostrar el ''antes'' en pantalla y voltear la cámara o el objeto para la revelación.', 'Formato de anécdota: ''me di cuenta de algo…''.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('REV-04', 'Revelación', 'La señal que nadie lee', 'Cuando [comportamiento pequeño] pasa, ya [consecuencia grande] está en camino.', '["revelacion", "advertencia"]', '["autoridad", "educacion"]', '["experto", "directo"]', '["todas"]', 2, 'Cuando tu mejor persona deja de opinar en las reuniones, la renuncia ya está escrita.', 'Hay señales que indican que un empleado podría renunciar.', 'Promete lo que está detrás; la primera línea del cuerpo debe empezar a pagarlo.', 'Carrusel: portada con ''lo que parece / lo que es''. Cada slide revela una capa.', 'Mostrar el ''antes'' en pantalla y voltear la cámara o el objeto para la revelación.', 'Formato de anécdota: ''me di cuenta de algo…''.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('REV-05', 'Revelación', 'Lo que de verdad significa la frase', 'Cuando alguien dice ''[frase típica]'', lo que está diciendo es ''[traducción]''.', '["revelacion", "humor"]', '["alcance", "conversacion"]', '["divertido", "irreverente"]', '["todas"]', 1, 'Cuando el cliente dice ''déjame lo pienso'', casi siempre está diciendo ''no me convenciste y me da pena decírtelo''.', 'Cuando un cliente duda, hay que entender sus objeciones.', 'Promete lo que está detrás; la primera línea del cuerpo debe empezar a pagarlo.', 'Carrusel: portada con ''lo que parece / lo que es''. Cada slide revela una capa.', 'Mostrar el ''antes'' en pantalla y voltear la cámara o el objeto para la revelación.', 'Formato de anécdota: ''me di cuenta de algo…''.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('REV-06', 'Revelación', 'La pregunta que lo cambia todo', 'Una pregunta me mostró [verdad oculta]: ''[pregunta]''.', '["revelacion", "valor_practico"]', '["educacion", "autoridad"]', '["experto", "narrativo"]', '["todas"]', 2, 'Una pregunta me mostró por qué el equipo no crecía: ''¿quién aquí se siente capaz de decirle que no al gerente?''.', 'Hacer buenas preguntas es clave en el liderazgo.', 'Promete lo que está detrás; la primera línea del cuerpo debe empezar a pagarlo.', 'Carrusel: portada con ''lo que parece / lo que es''. Cada slide revela una capa.', 'Mostrar el ''antes'' en pantalla y voltear la cámara o el objeto para la revelación.', 'Formato de anécdota: ''me di cuenta de algo…''.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('REV-07', 'Revelación', 'El costo escondido', '[Decisión barata] te está saliendo carísima. La cuenta no aparece en [donde se mira].', '["revelacion", "miedo_perder"]', '["leads", "ventas"]', '["directo", "comercial"]', '["todas"]', 2, 'Contratar rápido para tapar el hueco te está saliendo carísimo. Esa cuenta no aparece en la nómina: aparece en el cliente que se va.', 'Contratar mal tiene costos que las empresas deben considerar.', 'Promete lo que está detrás; la primera línea del cuerpo debe empezar a pagarlo.', 'Carrusel: portada con ''lo que parece / lo que es''. Cada slide revela una capa.', 'Mostrar el ''antes'' en pantalla y voltear la cámara o el objeto para la revelación.', 'Formato de anécdota: ''me di cuenta de algo…''.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('REV-08', 'Revelación', 'Desmontar el ritual', '[Ritual de la industria] no sirve para lo que dicen. Sirve para [función real].', '["revelacion", "satira"]', '["conversacion", "posicionamiento"]', '["irreverente", "intelectual"]', '["todas"]', 3, 'La evaluación de desempeño anual no sirve para evaluar desempeño. Sirve para que nadie pueda decir que no hubo evaluación.', 'Las evaluaciones de desempeño deben modernizarse.', 'Promete lo que está detrás; la primera línea del cuerpo debe empezar a pagarlo.', 'Carrusel: portada con ''lo que parece / lo que es''. Cada slide revela una capa.', 'Mostrar el ''antes'' en pantalla y voltear la cámara o el objeto para la revelación.', 'Formato de anécdota: ''me di cuenta de algo…''.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('REV-09', 'Revelación', 'Lo que aprendí viendo a los que sí', 'Después de ver a [N/tipo] que sí lograron X, lo que tienen en común no es [lo esperado].', '["revelacion", "autoridad", "sorpresa"]', '["autoridad", "posicionamiento"]', '["experto", "intelectual"]', '["todas"]', 2, 'Después de trabajar con gerentes que sí logran que su gente se quede, lo que tienen en común no es el salario. Es que cumplen lo que dicen el viernes.', 'Los buenos gerentes tienen varias características en común.', 'Promete lo que está detrás; la primera línea del cuerpo debe empezar a pagarlo.', 'Carrusel: portada con ''lo que parece / lo que es''. Cada slide revela una capa.', 'Mostrar el ''antes'' en pantalla y voltear la cámara o el objeto para la revelación.', 'Formato de anécdota: ''me di cuenta de algo…''.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('REV-10', 'Revelación', 'La palabra trampa', 'Hay una palabra que delata [problema]: ''[palabra]''.', '["revelacion", "curiosidad", "especificidad"]', '["alcance", "educacion"]', '["conversacional", "experto"]', '["todas"]', 2, 'Hay una palabra que delata a un equipo con miedo: ''ojalá''.', 'El lenguaje de los equipos dice mucho de su cultura.', 'Promete lo que está detrás; la primera línea del cuerpo debe empezar a pagarlo.', 'Carrusel: portada con ''lo que parece / lo que es''. Cada slide revela una capa.', 'Mostrar el ''antes'' en pantalla y voltear la cámara o el objeto para la revelación.', 'Formato de anécdota: ''me di cuenta de algo…''.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('IDE-01', 'Identificación situacional', 'Cuando eres X y te pasa Y', 'Cuando eres [rol] y [situación específica].', '["identificacion", "humor"]', '["alcance", "comunidad"]', '["divertido", "conversacional"]', '["todas"]', 1, 'Cuando eres la única en la casa que sabe dónde está el uniforme de educación física.', 'Las mamás trabajadoras tienen muchas responsabilidades.', 'Situación hiperconcreta en la primera línea; el lector debe pensar ''esa soy yo''.', 'Reel o carrusel con la situación en texto grande; ideal para guardar y compartir.', 'Formato POV: ''cuando eres X y pasa Y''. Actuar la situación sin explicarla.', 'Funciona muy bien: invita a etiquetar a alguien.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('IDE-02', 'Identificación situacional', 'Nadie habla de este momento', 'Nadie habla del momento en que [microexperiencia].', '["identificacion", "revelacion"]', '["emocional", "comunidad"]', '["emocional", "profundo"]', '["todas"]', 1, 'Nadie habla del momento en que llegas a la casa y te quedas cinco minutos en el carro antes de entrar.', 'Es importante hablar de las emociones.', 'Situación hiperconcreta en la primera línea; el lector debe pensar ''esa soy yo''.', 'Reel o carrusel con la situación en texto grande; ideal para guardar y compartir.', 'Formato POV: ''cuando eres X y pasa Y''. Actuar la situación sin explicarla.', 'Funciona muy bien: invita a etiquetar a alguien.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('IDE-03', 'Identificación situacional', 'Si alguna vez…', 'Si alguna vez [acción secreta], esto es para ti.', '["identificacion", "pertenencia"]', '["comunidad", "emocional"]', '["conversacional", "emocional"]', '["todas"]', 1, 'Si alguna vez has fingido una llamada para salir de una reunión que no iba para ningún lado, esto es para ti.', 'Si te interesa la productividad, sigue leyendo.', 'Situación hiperconcreta en la primera línea; el lector debe pensar ''esa soy yo''.', 'Reel o carrusel con la situación en texto grande; ideal para guardar y compartir.', 'Formato POV: ''cuando eres X y pasa Y''. Actuar la situación sin explicarla.', 'Funciona muy bien: invita a etiquetar a alguien.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('IDE-04', 'Identificación situacional', 'La frase que te dijeron', '''[Frase que muchos escucharon]''. Si te la dijeron, [lo que dejó].', '["identificacion", "storytelling"]', '["emocional", "conversacion"]', '["emocional", "profundo"]', '["todas"]', 2, '''Tú puedes con todo.'' Si te lo dijeron mucho de niña, probablemente hoy no sabes pedir ayuda.', 'Las frases de la infancia nos afectan de adultos.', 'Situación hiperconcreta en la primera línea; el lector debe pensar ''esa soy yo''.', 'Reel o carrusel con la situación en texto grande; ideal para guardar y compartir.', 'Formato POV: ''cuando eres X y pasa Y''. Actuar la situación sin explicarla.', 'Funciona muy bien: invita a etiquetar a alguien.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('IDE-05', 'Identificación situacional', 'Lista de señales', 'Señales de que [situación], sin que nadie te lo haya dicho:', '["identificacion", "valor_practico"]', '["alcance", "educacion"]', '["conversacional", "divertido"]', '["todas"]', 1, 'Señales de que ya eres jefe, aunque nadie te lo haya dicho: te da pánico el ''tienes un minuto?''.', 'Estas son las características de un buen jefe.', 'Situación hiperconcreta en la primera línea; el lector debe pensar ''esa soy yo''.', 'Reel o carrusel con la situación en texto grande; ideal para guardar y compartir.', 'Formato POV: ''cuando eres X y pasa Y''. Actuar la situación sin explicarla.', 'Funciona muy bien: invita a etiquetar a alguien.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('IDE-06', 'Identificación situacional', 'El pensamiento de las 11 p. m.', 'Son las [hora] y estás pensando en [preocupación concreta].', '["identificacion", "storytelling"]', '["emocional", "comunidad"]', '["emocional", "narrativo"]', '["todas"]', 1, 'Son las 11 de la noche y estás revisando si respondiste el correo del cliente con el tono correcto.', 'Muchos profesionales sufren de estrés por el trabajo.', 'Situación hiperconcreta en la primera línea; el lector debe pensar ''esa soy yo''.', 'Reel o carrusel con la situación en texto grande; ideal para guardar y compartir.', 'Formato POV: ''cuando eres X y pasa Y''. Actuar la situación sin explicarla.', 'Funciona muy bien: invita a etiquetar a alguien.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('IDE-07', 'Identificación situacional', 'Yo también fui ese', 'Yo era [persona que hoy critico]. Por eso sé [lo que se siente].', '["identificacion", "confesion"]', '["emocional", "autoridad"]', '["conversacional", "profundo"]', '["todas"]', 2, 'Yo era el gerente que respondía correos a medianoche y lo llamaba compromiso. Por eso sé lo que le hace a un equipo.', 'Los gerentes deben dar ejemplo de equilibrio.', 'Situación hiperconcreta en la primera línea; el lector debe pensar ''esa soy yo''.', 'Reel o carrusel con la situación en texto grande; ideal para guardar y compartir.', 'Formato POV: ''cuando eres X y pasa Y''. Actuar la situación sin explicarla.', 'Funciona muy bien: invita a etiquetar a alguien.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('IDE-08', 'Identificación situacional', 'Dos tipos de personas', 'Hay dos tipos de personas cuando [situación]: [A] y [B].', '["identificacion", "humor", "comparacion"]', '["alcance", "comentarios"]', '["divertido", "irreverente"]', '["todas"]', 1, 'Hay dos tipos de personas cuando llega la reunión de presupuesto: las que traen Excel y las que traen fe.', 'Existen distintos perfiles de personas en las empresas.', 'Situación hiperconcreta en la primera línea; el lector debe pensar ''esa soy yo''.', 'Reel o carrusel con la situación en texto grande; ideal para guardar y compartir.', 'Formato POV: ''cuando eres X y pasa Y''. Actuar la situación sin explicarla.', 'Funciona muy bien: invita a etiquetar a alguien.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('IDE-09', 'Identificación situacional', 'La conversación que todos tuvimos', 'Todos hemos tenido esta conversación: ''[diálogo breve]''.', '["identificacion", "humor"]', '["comentarios", "alcance"]', '["divertido", "conversacional"]', '["todas"]', 2, 'Todos hemos tenido esta conversación: ''¿Me puedes mandar lo de ayer?'' ''¿Qué de ayer?'' ''Lo que hablamos.'' ''No hablamos.''', 'La comunicación en los equipos es fundamental.', 'Situación hiperconcreta en la primera línea; el lector debe pensar ''esa soy yo''.', 'Reel o carrusel con la situación en texto grande; ideal para guardar y compartir.', 'Formato POV: ''cuando eres X y pasa Y''. Actuar la situación sin explicarla.', 'Funciona muy bien: invita a etiquetar a alguien.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('IDE-10', 'Identificación situacional', 'El orgullo secreto', 'Nadie lo sabe, pero cada vez que [pequeña victoria], [reacción exagerada].', '["identificacion", "humor"]', '["comunidad", "alcance"]', '["divertido", "emocional"]', '["todas"]', 2, 'Nadie lo sabe, pero cada vez que salgo de una reunión cinco minutos antes, me siento como si hubiera ganado un Grammy.', 'Las pequeñas victorias son importantes.', 'Situación hiperconcreta en la primera línea; el lector debe pensar ''esa soy yo''.', 'Reel o carrusel con la situación en texto grande; ideal para guardar y compartir.', 'Formato POV: ''cuando eres X y pasa Y''. Actuar la situación sin explicarla.', 'Funciona muy bien: invita a etiquetar a alguien.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('HUM-01', 'Humor y violación benigna', 'Traducción simultánea', 'Lo que dicen: ''[frase]''. Lo que significa: ''[traducción honesta]''.', '["humor", "revelacion", "ironia"]', '["alcance", "comentarios"]', '["divertido", "sarcastico"]', '["todas"]', 1, 'Lo que dice la oferta laboral: ''ambiente dinámico''. Lo que significa: ''nadie sabe qué está haciendo''.', 'Las ofertas laborales a veces no son claras.', 'Humor seco y corto; nada de emojis de risa. El remate en la segunda línea.', 'Reel con remate visual o meme propio. El texto acompaña, no explica el chiste.', 'Sketch: la situación se actúa; el texto en pantalla pone el contexto (''yo en la reunión de las 8'').', 'Funciona con humor costumbrista; invita a etiquetar.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('HUM-02', 'Humor y violación benigna', 'Exageración costumbrista', 'En [lugar/sector], [situación normal] se vive como [exageración].', '["humor", "identificacion"]', '["alcance", "comunidad"]', '["divertido", "irreverente"]', '["todas"]', 2, 'En Bogotá, decir ''ya casi llego'' es un estado mental, no una ubicación.', 'En las ciudades grandes la movilidad es complicada.', 'Humor seco y corto; nada de emojis de risa. El remate en la segunda línea.', 'Reel con remate visual o meme propio. El texto acompaña, no explica el chiste.', 'Sketch: la situación se actúa; el texto en pantalla pone el contexto (''yo en la reunión de las 8'').', 'Funciona con humor costumbrista; invita a etiquetar.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('HUM-03', 'Humor y violación benigna', 'Instrucciones absurdas', 'Cómo [lograr algo malo] en [N] pasos: 1. [paso obvio y ridículo]…', '["satira", "humor", "valor_practico"]', '["alcance", "educacion"]', '["sarcastico", "irreverente"]', '["todas"]', 2, 'Cómo perder a tu mejor empleado en tres pasos. Uno: prémialo con más trabajo.', 'Errores comunes que hacen que los empleados renuncien.', 'Humor seco y corto; nada de emojis de risa. El remate en la segunda línea.', 'Reel con remate visual o meme propio. El texto acompaña, no explica el chiste.', 'Sketch: la situación se actúa; el texto en pantalla pone el contexto (''yo en la reunión de las 8'').', 'Funciona con humor costumbrista; invita a etiquetar.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('HUM-04', 'Humor y violación benigna', 'La reseña imposible', 'Le doy [N] estrellas a [experiencia cotidiana]: [crítica exagerada].', '["humor", "ironia"]', '["alcance", "comentarios"]', '["divertido", "sarcastico"]', '["todas"]', 2, 'Le doy dos estrellas a la reunión de ''seguimiento rápido'': de rápido no tuvo nada y el seguimiento sigue pendiente.', 'Las reuniones deben ser más eficientes.', 'Humor seco y corto; nada de emojis de risa. El remate en la segunda línea.', 'Reel con remate visual o meme propio. El texto acompaña, no explica el chiste.', 'Sketch: la situación se actúa; el texto en pantalla pone el contexto (''yo en la reunión de las 8'').', 'Funciona con humor costumbrista; invita a etiquetar.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('HUM-05', 'Humor y violación benigna', 'Expectativa vs. realidad', 'Expectativa: [ideal]. Realidad: [lo que pasa].', '["humor", "comparacion", "identificacion"]', '["alcance", "comunidad"]', '["divertido", "conversacional"]', '["todas"]', 1, 'Expectativa: ''este fin de semana descanso''. Realidad: lavé, cociné, hice tareas y el lunes llegué más cansada.', 'A veces el descanso no es lo que esperamos.', 'Humor seco y corto; nada de emojis de risa. El remate en la segunda línea.', 'Reel con remate visual o meme propio. El texto acompaña, no explica el chiste.', 'Sketch: la situación se actúa; el texto en pantalla pone el contexto (''yo en la reunión de las 8'').', 'Funciona con humor costumbrista; invita a etiquetar.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('HUM-06', 'Humor y violación benigna', 'Personificar el objeto', 'Si [objeto/sistema] pudiera hablar, diría: ''[queja]''.', '["humor", "satira"]', '["alcance", "comentarios"]', '["divertido", "irreverente"]', '["todas"]', 2, 'Si tu CRM pudiera hablar, diría: ''llevo seis meses con el mismo cliente en etapa de negociación, ¿estamos bien?''.', 'Hay que mantener actualizado el CRM.', 'Humor seco y corto; nada de emojis de risa. El remate en la segunda línea.', 'Reel con remate visual o meme propio. El texto acompaña, no explica el chiste.', 'Sketch: la situación se actúa; el texto en pantalla pone el contexto (''yo en la reunión de las 8'').', 'Funciona con humor costumbrista; invita a etiquetar.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('HUM-07', 'Humor y violación benigna', 'Falso anuncio', 'Se busca: [rol imposible] con [requisitos absurdos que todos reconocen].', '["satira", "identificacion"]', '["alcance", "conversacion"]', '["sarcastico", "provocador"]', '["rrhh", "maternidad", "emprendimiento"]', 2, 'Se busca: junior con 10 años de experiencia, inglés nativo, disponibilidad total y ''ganas de crecer''. Salario: a convenir (bajo).', 'Las vacantes a veces piden demasiado.', 'Humor seco y corto; nada de emojis de risa. El remate en la segunda línea.', 'Reel con remate visual o meme propio. El texto acompaña, no explica el chiste.', 'Sketch: la situación se actúa; el texto en pantalla pone el contexto (''yo en la reunión de las 8'').', 'Funciona con humor costumbrista; invita a etiquetar.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('HUM-08', 'Humor y violación benigna', 'El glosario honesto', 'Diccionario de [sector], edición honesta: [término] = [definición real].', '["humor", "ironia", "pertenencia"]', '["alcance", "comunidad"]', '["divertido", "sarcastico"]', '["todas"]', 1, 'Diccionario de oficina, edición honesta. ''Lo revisamos y te confirmo'': nunca te van a confirmar.', 'Algunas expresiones de oficina son confusas.', 'Humor seco y corto; nada de emojis de risa. El remate en la segunda línea.', 'Reel con remate visual o meme propio. El texto acompaña, no explica el chiste.', 'Sketch: la situación se actúa; el texto en pantalla pone el contexto (''yo en la reunión de las 8'').', 'Funciona con humor costumbrista; invita a etiquetar.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('HUM-09', 'Humor y violación benigna', 'Comparación desproporcionada', '[Tarea pequeña] me genera más [emoción] que [cosa enorme].', '["humor", "identificacion"]', '["alcance", "comunidad"]', '["divertido", "conversacional"]', '["todas"]', 1, 'Me da más miedo un ''tenemos que hablar'' por Slack que una auditoría de la DIAN.', 'La comunicación digital puede generar ansiedad.', 'Humor seco y corto; nada de emojis de risa. El remate en la segunda línea.', 'Reel con remate visual o meme propio. El texto acompaña, no explica el chiste.', 'Sketch: la situación se actúa; el texto en pantalla pone el contexto (''yo en la reunión de las 8'').', 'Funciona con humor costumbrista; invita a etiquetar.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('HUM-10', 'Humor y violación benigna', 'Lo dijo mi mamá', 'Mi mamá resumió [concepto complejo] mejor que cualquier [experto]: ''[frase]''.', '["humor", "autoridad", "identificacion"]', '["alcance", "emocional"]', '["divertido", "emocional"]', '["todas"]', 2, 'Mi mamá resumió el liderazgo mejor que cualquier libro: ''si tienes que gritar para que te hagan caso, ya perdiste''.', 'El liderazgo se aprende de muchas fuentes.', 'Humor seco y corto; nada de emojis de risa. El remate en la segunda línea.', 'Reel con remate visual o meme propio. El texto acompaña, no explica el chiste.', 'Sketch: la situación se actúa; el texto en pantalla pone el contexto (''yo en la reunión de las 8'').', 'Funciona con humor costumbrista; invita a etiquetar.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('POL-01', 'Controversia y opinión impopular', 'Opinión impopular', 'Opinión impopular: [postura defendible que incomoda].', '["controversia", "contradiccion"]', '["conversacion", "alcance"]', '["polemico", "directo"]', '["todas"]', 1, 'Opinión impopular: la mayoría de los programas de bienestar existen para que la empresa se sienta bien, no el empleado.', 'Opinión: el bienestar laboral es importante.', 'La postura en la primera línea; el argumento empieza en la segunda. Cierra con una pregunta honesta.', 'Carrusel ''opinión impopular'' con argumento por slide; evitar el tono de pelea.', 'Mirar a cámara, decir la postura sin preámbulo. Pausa de un segundo antes del argumento.', 'Cuidado: en Facebook la polémica escala rápido. Suavizar con experiencia personal.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('POL-02', 'Controversia y opinión impopular', 'Voy a decir algo que incomoda a…', 'Voy a decir algo que probablemente incomode a quienes [grupo].', '["controversia", "curiosidad"]', '["conversacion", "posicionamiento"]', '["provocador", "confrontacional"]', '["todas"]', 2, 'Voy a decir algo que probablemente incomode a quienes dirigen áreas de talento: el problema casi nunca es el talento.', 'Quiero compartir una reflexión sobre talento.', 'La postura en la primera línea; el argumento empieza en la segunda. Cierra con una pregunta honesta.', 'Carrusel ''opinión impopular'' con argumento por slide; evitar el tono de pelea.', 'Mirar a cámara, decir la postura sin preámbulo. Pausa de un segundo antes del argumento.', 'Cuidado: en Facebook la polémica escala rápido. Suavizar con experiencia personal.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('POL-03', 'Controversia y opinión impopular', 'Deja de hacer X', 'Deja de [práctica aceptada]. [Razón corta y dura].', '["controversia", "advertencia"]', '["alcance", "autoridad"]', '["confrontacional", "directo"]', '["todas"]', 1, 'Deja de pedir ''feedback'' si no vas a cambiar nada. Eso no es escuchar, es coleccionar opiniones.', 'Es importante pedir feedback y actuar sobre él.', 'La postura en la primera línea; el argumento empieza en la segunda. Cierra con una pregunta honesta.', 'Carrusel ''opinión impopular'' con argumento por slide; evitar el tono de pelea.', 'Mirar a cámara, decir la postura sin preámbulo. Pausa de un segundo antes del argumento.', 'Cuidado: en Facebook la polémica escala rápido. Suavizar con experiencia personal.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('POL-04', 'Controversia y opinión impopular', 'Lo que está sobrevalorado', '[Práctica de moda] está sobrevalorado. [Lo subvalorado] no.', '["controversia", "comparacion"]', '["conversacion", "posicionamiento"]', '["polemico", "experto"]', '["todas"]', 1, 'La ''marca personal'' está sobrevalorada. Tener algo que decir, no.', 'La marca personal tiene pros y contras.', 'La postura en la primera línea; el argumento empieza en la segunda. Cierra con una pregunta honesta.', 'Carrusel ''opinión impopular'' con argumento por slide; evitar el tono de pelea.', 'Mirar a cámara, decir la postura sin preámbulo. Pausa de un segundo antes del argumento.', 'Cuidado: en Facebook la polémica escala rápido. Suavizar con experiencia personal.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('POL-05', 'Controversia y opinión impopular', 'Me van a odiar por esto', 'Sé que me van a [reacción], pero [postura].', '["controversia", "confesion"]', '["conversacion", "alcance"]', '["provocador", "conversacional"]', '["todas"]', 1, 'Sé que me van a llover comentarios, pero no creo que tu jefe tenga que ser tu amigo.', 'Esta es mi opinión sobre la relación jefe-empleado.', 'La postura en la primera línea; el argumento empieza en la segunda. Cierra con una pregunta honesta.', 'Carrusel ''opinión impopular'' con argumento por slide; evitar el tono de pelea.', 'Mirar a cámara, decir la postura sin preámbulo. Pausa de un segundo antes del argumento.', 'Cuidado: en Facebook la polémica escala rápido. Suavizar con experiencia personal.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('POL-06', 'Controversia y opinión impopular', 'El enemigo es la práctica', '[Práctica del sector] le está haciendo más daño a [víctima] que [amenaza que todos temen].', '["controversia", "enemigo_comun"]', '["posicionamiento", "conversacion"]', '["confrontacional", "intelectual"]', '["todas"]', 2, 'Las reuniones de ''alineación'' le están haciendo más daño a tu empresa que cualquier competidor.', 'Las reuniones improductivas afectan a las empresas.', 'La postura en la primera línea; el argumento empieza en la segunda. Cierra con una pregunta honesta.', 'Carrusel ''opinión impopular'' con argumento por slide; evitar el tono de pelea.', 'Mirar a cámara, decir la postura sin preámbulo. Pausa de un segundo antes del argumento.', 'Cuidado: en Facebook la polémica escala rápido. Suavizar con experiencia personal.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('POL-07', 'Controversia y opinión impopular', 'Anti-marketing', 'No me gusta [lo que todos persiguen]. Por eso [consecuencia que me hace más valioso].', '["controversia", "contradiccion", "autoridad"]', '["posicionamiento", "leads"]', '["irreverente", "directo"]', '["todas"]', 3, 'No me gusta vender por LinkedIn. Por eso casi no publico ofertas, y casi todos mis clientes llegan por una publicación.', 'Uso LinkedIn para conseguir clientes de manera estratégica.', 'La postura en la primera línea; el argumento empieza en la segunda. Cierra con una pregunta honesta.', 'Carrusel ''opinión impopular'' con argumento por slide; evitar el tono de pelea.', 'Mirar a cámara, decir la postura sin preámbulo. Pausa de un segundo antes del argumento.', 'Cuidado: en Facebook la polémica escala rápido. Suavizar con experiencia personal.', 'Mecanismo observado: Isra Bravo, X, 2020-02-26 (''No me gustan las RRSS y apenas entro…'').', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('POL-08', 'Controversia y opinión impopular', 'La pregunta que nadie se atreve', 'Alguien tenía que decirlo: [pregunta/afirmación tabú en el sector].', '["controversia", "pertenencia"]', '["conversacion", "comunidad"]', '["provocador", "directo"]', '["todas"]', 2, 'Alguien tenía que decirlo: a muchos líderes no les falta tiempo para su gente. Les falta ganas.', 'Los líderes deben dedicar tiempo a su equipo.', 'La postura en la primera línea; el argumento empieza en la segunda. Cierra con una pregunta honesta.', 'Carrusel ''opinión impopular'' con argumento por slide; evitar el tono de pelea.', 'Mirar a cámara, decir la postura sin preámbulo. Pausa de un segundo antes del argumento.', 'Cuidado: en Facebook la polémica escala rápido. Suavizar con experiencia personal.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('POL-09', 'Controversia y opinión impopular', 'Defender lo indefendible', 'Voy a defender [lo que todos critican]: [argumento sorprendente].', '["controversia", "sorpresa"]', '["conversacion", "posicionamiento"]', '["intelectual", "provocador"]', '["todas"]', 3, 'Voy a defender al jefe que no deja trabajar remoto: muchas veces no es control, es que no sabe dirigir sin ver.', 'Hay argumentos a favor y en contra del trabajo remoto.', 'La postura en la primera línea; el argumento empieza en la segunda. Cierra con una pregunta honesta.', 'Carrusel ''opinión impopular'' con argumento por slide; evitar el tono de pelea.', 'Mirar a cámara, decir la postura sin preámbulo. Pausa de un segundo antes del argumento.', 'Cuidado: en Facebook la polémica escala rápido. Suavizar con experiencia personal.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('POL-10', 'Controversia y opinión impopular', 'Dilema de dos verdades', '¿Es más [X] [opción A]… o [opción B]?', '["controversia", "identificacion"]', '["comentarios", "conversacion"]', '["conversacional", "provocador"]', '["todas"]', 1, '¿Es peor un jefe que grita… o uno que nunca dice nada?', '¿Qué opinas de los jefes?', 'Solo para objetivo de comentarios. Da tu postura en la línea 3 para no parecer encuesta vacía.', 'Carrusel ''opinión impopular'' con argumento por slide; evitar el tono de pelea.', 'Mirar a cámara, decir la postura sin preámbulo. Pausa de un segundo antes del argumento.', 'Cuidado: en Facebook la polémica escala rápido. Suavizar con experiencia personal.', 'Mecanismo observado: Euge Oller, X, 2025-08-24 (''¿Era más fácil emprender antes… o lo es ahora?'').', true);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('CNF-01', 'Confesión', 'Cometí este error y me costó…', 'Cometí [error concreto] y me costó [costo concreto].', '["confesion", "especificidad"]', '["autoridad", "emocional"]', '["narrativo", "conversacional"]', '["todas"]', 1, 'Contraté a un amigo para un cargo directivo y me costó la amistad y medio año de resultados.', 'Todos cometemos errores al contratar.', 'Primera persona, sin dramatismo. El error en la primera línea y el costo en la segunda.', 'Reel hablado a cámara o carrusel con foto real. La vulnerabilidad pierde fuerza si está demasiado producida.', 'Cámara cercana, tono bajo, como un secreto: ''les voy a contar algo que nunca conté''.', 'Funciona muy bien: genera mensajes de apoyo y conversación.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('CNF-02', 'Confesión', 'Falsa confesión', 'Lo confieso: [algo que en realidad es una virtud o una obsesión de nicho].', '["confesion", "ironia", "humor"]', '["alcance", "posicionamiento"]', '["divertido", "conversacional"]', '["todas"]', 2, 'Lo confieso: leo los términos y condiciones de los contratos. Todos. Y por eso no he firmado varios.', 'Es importante leer los contratos.', 'Primera persona, sin dramatismo. El error en la primera línea y el costo en la segunda.', 'Reel hablado a cámara o carrusel con foto real. La vulnerabilidad pierde fuerza si está demasiado producida.', 'Cámara cercana, tono bajo, como un secreto: ''les voy a contar algo que nunca conté''.', 'Funciona muy bien: genera mensajes de apoyo y conversación.', 'Mecanismo observado: Vilma Núñez, LinkedIn (''Lo confieso, soy una Growth Marketer'').', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('CNF-03', 'Confesión', 'Lo que nunca le dije a nadie', 'Nunca le había contado esto a nadie de [contexto]: [confesión].', '["confesion", "intriga"]', '["emocional", "comunidad"]', '["emocional", "profundo"]', '["todas"]', 2, 'Nunca le había contado esto a nadie de mi trabajo: la semana del ascenso estuve a punto de renunciar.', 'Quiero compartir algo personal.', 'Primera persona, sin dramatismo. El error en la primera línea y el costo en la segunda.', 'Reel hablado a cámara o carrusel con foto real. La vulnerabilidad pierde fuerza si está demasiado producida.', 'Cámara cercana, tono bajo, como un secreto: ''les voy a contar algo que nunca conté''.', 'Funciona muy bien: genera mensajes de apoyo y conversación.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('CNF-04', 'Confesión', 'Estaba equivocado sobre X', 'Durante [tiempo] creí que [creencia]. Estaba equivocado.', '["confesion", "contradiccion"]', '["autoridad", "educacion"]', '["intelectual", "conversacional"]', '["todas"]', 1, 'Durante diez años creí que la gente buena se queda si le pagas bien. Estaba equivocado.', 'He aprendido mucho sobre retención de talento.', 'Primera persona, sin dramatismo. El error en la primera línea y el costo en la segunda.', 'Reel hablado a cámara o carrusel con foto real. La vulnerabilidad pierde fuerza si está demasiado producida.', 'Cámara cercana, tono bajo, como un secreto: ''les voy a contar algo que nunca conté''.', 'Funciona muy bien: genera mensajes de apoyo y conversación.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('CNF-05', 'Confesión', 'El momento en que me di cuenta', 'Me di cuenta de que [problema mío] el día que [escena concreta].', '["confesion", "storytelling"]', '["emocional", "identificacion"]', '["narrativo", "emocional"]', '["todas"]', 2, 'Me di cuenta de que estaba quemada el día que lloré porque se acabó el café de la oficina.', 'El burnout es una realidad en muchas profesionales.', 'Primera persona, sin dramatismo. El error en la primera línea y el costo en la segunda.', 'Reel hablado a cámara o carrusel con foto real. La vulnerabilidad pierde fuerza si está demasiado producida.', 'Cámara cercana, tono bajo, como un secreto: ''les voy a contar algo que nunca conté''.', 'Funciona muy bien: genera mensajes de apoyo y conversación.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('CNF-06', 'Confesión', 'Me da vergüenza admitirlo', 'Me da vergüenza admitirlo, pero [conducta poco profesional/humana].', '["confesion", "identificacion"]', '["comunidad", "alcance"]', '["conversacional", "divertido"]', '["todas"]', 1, 'Me da vergüenza admitirlo, pero ensayo en la ducha las conversaciones difíciles con mis clientes.', 'Prepararse para conversaciones difíciles es importante.', 'Primera persona, sin dramatismo. El error en la primera línea y el costo en la segunda.', 'Reel hablado a cámara o carrusel con foto real. La vulnerabilidad pierde fuerza si está demasiado producida.', 'Cámara cercana, tono bajo, como un secreto: ''les voy a contar algo que nunca conté''.', 'Funciona muy bien: genera mensajes de apoyo y conversación.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('CNF-07', 'Confesión', 'Lo que hice mal como líder', 'El peor error que cometí como [rol] no fue [error obvio]. Fue [error sutil].', '["confesion", "revelacion", "autoridad"]', '["autoridad", "posicionamiento"]', '["experto", "profundo"]', '["todas"]', 2, 'El peor error que cometí como gerente no fue despedir a alguien. Fue no despedirlo a tiempo.', 'Los gerentes también cometen errores.', 'Primera persona, sin dramatismo. El error en la primera línea y el costo en la segunda.', 'Reel hablado a cámara o carrusel con foto real. La vulnerabilidad pierde fuerza si está demasiado producida.', 'Cámara cercana, tono bajo, como un secreto: ''les voy a contar algo que nunca conté''.', 'Funciona muy bien: genera mensajes de apoyo y conversación.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('CNF-08', 'Confesión', 'Fracaso con número', '[Cifra real] [unidad] perdidos por [decisión]. Esto es lo que haría distinto.', '["confesion", "especificidad", "valor_practico"]', '["autoridad", "leads"]', '["directo", "experto"]', '["todas"]', 2, 'Seis meses y una buena parte de mis ahorros perdidos por lanzar sin preguntarle a un solo cliente. Esto es lo que haría distinto.', 'Emprender implica riesgos.', 'Primera persona, sin dramatismo. El error en la primera línea y el costo en la segunda.', 'Reel hablado a cámara o carrusel con foto real. La vulnerabilidad pierde fuerza si está demasiado producida.', 'Cámara cercana, tono bajo, como un secreto: ''les voy a contar algo que nunca conté''.', 'Funciona muy bien: genera mensajes de apoyo y conversación.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('CNF-09', 'Confesión', 'No sé hacer X (y está bien)', 'Llevo [tiempo] en [área] y todavía no sé [habilidad básica].', '["confesion", "sorpresa", "identificacion"]', '["alcance", "comunidad"]', '["conversacional", "divertido"]', '["todas"]', 1, 'Llevo 15 años en Recursos Humanos y todavía no sé dar una mala noticia sin que me suden las manos.', 'Dar malas noticias es difícil.', 'Primera persona, sin dramatismo. El error en la primera línea y el costo en la segunda.', 'Reel hablado a cámara o carrusel con foto real. La vulnerabilidad pierde fuerza si está demasiado producida.', 'Cámara cercana, tono bajo, como un secreto: ''les voy a contar algo que nunca conté''.', 'Funciona muy bien: genera mensajes de apoyo y conversación.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('CNF-10', 'Confesión', 'La versión que no publiqué', 'Esta es la versión de [logro] que no puse en LinkedIn.', '["confesion", "revelacion"]', '["emocional", "conversacion"]', '["emocional", "irreverente"]', '["todas"]', 2, 'Esta es la versión de mi ''nuevo reto profesional'' que no puse en LinkedIn: me despidieron un martes por correo.', 'Detrás de los anuncios profesionales hay historias.', 'Primera persona, sin dramatismo. El error en la primera línea y el costo en la segunda.', 'Reel hablado a cámara o carrusel con foto real. La vulnerabilidad pierde fuerza si está demasiado producida.', 'Cámara cercana, tono bajo, como un secreto: ''les voy a contar algo que nunca conté''.', 'Funciona muy bien: genera mensajes de apoyo y conversación.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('ADV-01', 'Advertencia y pérdida', 'Si estás haciendo X, cuidado con Y', 'Si estás [haciendo X], cuidado con [consecuencia no obvia].', '["advertencia", "especificidad"]', '["educacion", "leads"]', '["directo", "experto"]', '["todas"]', 1, 'Si estás contratando por recomendación de un amigo, cuidado con lo que pasa el día que tengas que corregirlo.', 'Ten cuidado al contratar.', 'La advertencia debe ser específica y proporcional; nada de mayúsculas ni alarmas.', 'Carrusel ''si haces X, revisa esto''. Útil para guardar.', 'Texto en pantalla ''si estás haciendo X, para''. Mano levantada en el segundo 0.', 'Formato de aviso entre conocidos: ''les cuento para que no les pase''.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('ADV-02', 'Advertencia y pérdida', 'Lo que te está costando no hacer X', 'No [acción] te está costando [pérdida concreta y visible].', '["miedo_perder", "revelacion"]', '["leads", "ventas"]', '["directo", "comercial"]', '["todas"]', 1, 'No hacer entrevistas de salida te está costando la única información honesta que vas a recibir de tu empresa.', 'Las entrevistas de salida son útiles.', 'La advertencia debe ser específica y proporcional; nada de mayúsculas ni alarmas.', 'Carrusel ''si haces X, revisa esto''. Útil para guardar.', 'Texto en pantalla ''si estás haciendo X, para''. Mano levantada en el segundo 0.', 'Formato de aviso entre conocidos: ''les cuento para que no les pase''.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('ADV-03', 'Advertencia y pérdida', 'El error silencioso', 'Hay un error que [grupo] comete sin darse cuenta, y se nota en [síntoma].', '["advertencia", "curiosidad"]', '["educacion", "autoridad"]', '["experto", "conversacional"]', '["todas"]', 1, 'Hay un error que casi todos los fundadores cometen sin darse cuenta, y se nota en que el equipo te pregunta todo.', 'Los fundadores deben aprender a delegar.', 'La advertencia debe ser específica y proporcional; nada de mayúsculas ni alarmas.', 'Carrusel ''si haces X, revisa esto''. Útil para guardar.', 'Texto en pantalla ''si estás haciendo X, para''. Mano levantada en el segundo 0.', 'Formato de aviso entre conocidos: ''les cuento para que no les pase''.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('ADV-04', 'Advertencia y pérdida', 'Antes de firmar/decidir', 'Antes de [decisión importante], hazte esta pregunta: ''[pregunta]''.', '["advertencia", "valor_practico"]', '["educacion", "leads"]', '["experto", "directo"]', '["todas"]', 1, 'Antes de aceptar esa oferta con mejor salario, hazte esta pregunta: ''¿con quién voy a almorzar todos los días?''.', 'Evalúa bien las ofertas laborales.', 'La advertencia debe ser específica y proporcional; nada de mayúsculas ni alarmas.', 'Carrusel ''si haces X, revisa esto''. Útil para guardar.', 'Texto en pantalla ''si estás haciendo X, para''. Mano levantada en el segundo 0.', 'Formato de aviso entre conocidos: ''les cuento para que no les pase''.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('ADV-05', 'Advertencia y pérdida', 'La fecha límite real', 'Tienes hasta [momento concreto] para [acción]. Después [consecuencia].', '["miedo_perder", "especificidad"]', '["ventas", "leads"]', '["directo", "comercial"]', '["todas"]', 2, 'Tienes hasta el primer mes para corregir a un nuevo empleado sin que suene a ataque. Después ya es costumbre.', 'Es importante dar retroalimentación temprana.', 'La advertencia debe ser específica y proporcional; nada de mayúsculas ni alarmas.', 'Carrusel ''si haces X, revisa esto''. Útil para guardar.', 'Texto en pantalla ''si estás haciendo X, para''. Mano levantada en el segundo 0.', 'Formato de aviso entre conocidos: ''les cuento para que no les pase''.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('ADV-06', 'Advertencia y pérdida', 'Señal de alarma disfrazada', 'Si [algo que parece bueno] pasa en tu [contexto], no celebres todavía.', '["advertencia", "contradiccion"]', '["autoridad", "educacion"]', '["experto", "provocador"]', '["todas"]', 2, 'Si en tu empresa nadie se queja, no celebres todavía. Puede que ya nadie crea que vale la pena.', 'La ausencia de quejas no siempre es buena.', 'La advertencia debe ser específica y proporcional; nada de mayúsculas ni alarmas.', 'Carrusel ''si haces X, revisa esto''. Útil para guardar.', 'Texto en pantalla ''si estás haciendo X, para''. Mano levantada en el segundo 0.', 'Formato de aviso entre conocidos: ''les cuento para que no les pase''.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('ADV-07', 'Advertencia y pérdida', 'Lo que vas a lamentar en 5 años', 'En [tiempo] no vas a lamentar [lo que te preocupa hoy]. Vas a lamentar [lo que ignoras].', '["miedo_perder", "aspiracion"]', '["emocional", "posicionamiento"]', '["profundo", "emocional"]', '["todas"]', 2, 'En diez años no vas a lamentar la reunión que te perdiste. Vas a lamentar la obra de teatro de tu hija que te perdiste por esa reunión.', 'Hay que equilibrar el trabajo y la familia.', 'La advertencia debe ser específica y proporcional; nada de mayúsculas ni alarmas.', 'Carrusel ''si haces X, revisa esto''. Útil para guardar.', 'Texto en pantalla ''si estás haciendo X, para''. Mano levantada en el segundo 0.', 'Formato de aviso entre conocidos: ''les cuento para que no les pase''.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('ADV-08', 'Advertencia y pérdida', 'Trampa en la que caí', 'Caí en esta trampa y casi [consecuencia]: [trampa].', '["advertencia", "confesion"]', '["educacion", "emocional"]', '["narrativo", "conversacional"]', '["todas"]', 1, 'Caí en esta trampa y casi pierdo mi mejor cliente: responder rápido en vez de responder bien.', 'Responder bien es mejor que responder rápido.', 'La advertencia debe ser específica y proporcional; nada de mayúsculas ni alarmas.', 'Carrusel ''si haces X, revisa esto''. Útil para guardar.', 'Texto en pantalla ''si estás haciendo X, para''. Mano levantada en el segundo 0.', 'Formato de aviso entre conocidos: ''les cuento para que no les pase''.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('ADV-09', 'Advertencia y pérdida', 'Cuánto cuesta realmente', '¿Sabes cuánto te cuesta [problema habitual]? Haz esta cuenta: [cuenta simple].', '["miedo_perder", "especificidad", "valor_practico"]', '["leads", "ventas"]', '["experto", "comercial"]', '["todas"]', 2, '¿Sabes cuánto te cuesta una reunión semanal de una hora con ocho gerentes? Multiplica sus salarios por hora y por 48 semanas.', 'Las reuniones tienen un costo oculto.', 'La advertencia debe ser específica y proporcional; nada de mayúsculas ni alarmas.', 'Carrusel ''si haces X, revisa esto''. Útil para guardar.', 'Texto en pantalla ''si estás haciendo X, para''. Mano levantada en el segundo 0.', 'Formato de aviso entre conocidos: ''les cuento para que no les pase''.', '', true);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('ADV-10', 'Advertencia y pérdida', 'No lo hagas así', 'Si vas a [acción común], por favor no lo hagas [forma habitual].', '["advertencia", "valor_practico"]', '["educacion", "alcance"]', '["directo", "conversacional"]', '["todas"]', 1, 'Si vas a despedir a alguien, por favor no lo hagas un viernes a las 5 por videollamada.', 'Los despidos deben hacerse con respeto.', 'La advertencia debe ser específica y proporcional; nada de mayúsculas ni alarmas.', 'Carrusel ''si haces X, revisa esto''. Útil para guardar.', 'Texto en pantalla ''si estás haciendo X, para''. Mano levantada en el segundo 0.', 'Formato de aviso entre conocidos: ''les cuento para que no les pase''.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('TRA-01', 'Transformación', 'Hace X estaba en Y. Hoy…', 'Hace [tiempo] estaba [situación difícil concreta]. Hoy [situación actual concreta].', '["aspiracion", "storytelling"]', '["emocional", "leads"]', '["narrativo", "inspirador"]', '["todas"]', 1, 'Hace cuatro años vendía mis servicios por WhatsApp a quien me respondiera. Hoy digo que no a tres de cada cuatro clientes.', 'Mi carrera ha crecido mucho.', 'Antes y después concretos, sin presumir. El ''cómo'' es lo que se promete.', 'Carrusel antes/después o reel con dos tomas contrastadas.', 'Corte visual de antes a ahora con texto ''hace X tiempo / hoy''.', 'Historia personal con foto real del antes.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('TRA-02', 'Transformación', 'Lo único que cambié', 'Solo cambié [una cosa pequeña] y [resultado grande].', '["aspiracion", "especificidad", "curiosidad"]', '["alcance", "educacion"]', '["conversacional", "directo"]', '["todas"]', 1, 'Solo cambié la primera pregunta de mis reuniones de ventas y dejé de escuchar ''déjame lo pienso''.', 'Pequeños cambios pueden generar grandes resultados.', 'Antes y después concretos, sin presumir. El ''cómo'' es lo que se promete.', 'Carrusel antes/después o reel con dos tomas contrastadas.', 'Corte visual de antes a ahora con texto ''hace X tiempo / hoy''.', 'Historia personal con foto real del antes.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('TRA-03', 'Transformación', 'Experimento con restricción', '[Fecha] me puse un reto: lograr [X] sin [Y]. Esto pasó.', '["intriga", "especificidad", "curiosidad"]', '["alcance", "autoridad"]', '["narrativo", "conversacional"]', '["todas"]', 2, 'En enero me puse un reto: conseguir un cliente nuevo sin mandar un solo mensaje en frío. Esto pasó.', 'Hice un experimento de ventas.', 'Antes y después concretos, sin presumir. El ''cómo'' es lo que se promete.', 'Carrusel antes/después o reel con dos tomas contrastadas.', 'Corte visual de antes a ahora con texto ''hace X tiempo / hoy''.', 'Historia personal con foto real del antes.', 'Mecanismo observado: Euge Oller, X, 2024-07-22 (monetizar un hobby sin marca personal).', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('TRA-04', 'Transformación', 'De lo que me avergonzaba a lo que me define', 'Lo que antes escondía, hoy es [lo que me diferencia].', '["aspiracion", "confesion"]', '["posicionamiento", "emocional"]', '["inspirador", "profundo"]', '["todas"]', 2, 'Lo que antes escondía en las entrevistas, que crecí en el campo, hoy es lo que más me preguntan los clientes.', 'Nuestras raíces nos hacen únicos.', 'Antes y después concretos, sin presumir. El ''cómo'' es lo que se promete.', 'Carrusel antes/después o reel con dos tomas contrastadas.', 'Corte visual de antes a ahora con texto ''hace X tiempo / hoy''.', 'Historia personal con foto real del antes.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('TRA-05', 'Transformación', 'El día que dejé de…', 'El día que dejé de [hábito] empecé a [resultado].', '["aspiracion", "contradiccion"]', '["alcance", "emocional"]', '["directo", "inspirador"]', '["todas"]', 1, 'El día que dejé de responder correos antes de las 9, empecé a tener ideas.', 'Cambiar hábitos mejora la productividad.', 'Antes y después concretos, sin presumir. El ''cómo'' es lo que se promete.', 'Carrusel antes/después o reel con dos tomas contrastadas.', 'Corte visual de antes a ahora con texto ''hace X tiempo / hoy''.', 'Historia personal con foto real del antes.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('TRA-06', 'Transformación', 'Versión 1 vs. versión actual', 'Mi primer [producto/intento] vs. el de hoy. La diferencia no es [lo obvio].', '["comparacion", "revelacion"]', '["autoridad", "educacion"]', '["experto", "conversacional"]', '["todas"]', 2, 'Mi primera propuesta comercial tenía 30 páginas; la de hoy tiene dos. La diferencia no es el diseño: es que ahora sé qué problema estoy resolviendo.', 'He mejorado mis propuestas comerciales.', 'Antes y después concretos, sin presumir. El ''cómo'' es lo que se promete.', 'Carrusel antes/después o reel con dos tomas contrastadas.', 'Corte visual de antes a ahora con texto ''hace X tiempo / hoy''.', 'Historia personal con foto real del antes.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('TRA-07', 'Transformación', 'Lo que haría con lo que sé hoy', 'Si volviera a [punto de partida], haría esto en [tiempo]:', '["valor_practico", "autoridad"]', '["educacion", "leads"]', '["experto", "directo"]', '["todas"]', 1, 'Si volviera a empezar mi consultoría hoy, haría esto en los primeros 90 días:', 'Consejos para empezar una consultoría.', 'Antes y después concretos, sin presumir. El ''cómo'' es lo que se promete.', 'Carrusel antes/después o reel con dos tomas contrastadas.', 'Corte visual de antes a ahora con texto ''hace X tiempo / hoy''.', 'Historia personal con foto real del antes.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('TRA-08', 'Transformación', 'La transformación de otro', '[Persona/cliente] llegó [estado inicial]. [Tiempo] después [estado final]. Lo que cambió fue [sorpresa].', '["storytelling", "prueba_social", "sorpresa"]', '["leads", "ventas"]', '["narrativo", "comercial"]', '["todas"]', 2, 'Una gerente llegó convencida de que su equipo no servía. Dos meses después tenía el mismo equipo y otros resultados. Lo que cambió fue cómo daba instrucciones.', 'Nuestros clientes logran grandes resultados.', 'Antes y después concretos, sin presumir. El ''cómo'' es lo que se promete.', 'Carrusel antes/después o reel con dos tomas contrastadas.', 'Corte visual de antes a ahora con texto ''hace X tiempo / hoy''.', 'Historia personal con foto real del antes.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('TRA-09', 'Transformación', 'Pequeño hábito, gran giro', '[Hábito de N minutos] me cambió más que [inversión grande].', '["contradiccion", "aspiracion", "valor_practico"]', '["alcance", "educacion"]', '["conversacional", "inspirador"]', '["todas"]', 1, 'Diez minutos de caminar sin celular me cambiaron más que el curso de liderazgo de dos millones.', 'Los hábitos son importantes.', 'Antes y después concretos, sin presumir. El ''cómo'' es lo que se promete.', 'Carrusel antes/después o reel con dos tomas contrastadas.', 'Corte visual de antes a ahora con texto ''hace X tiempo / hoy''.', 'Historia personal con foto real del antes.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('TRA-10', 'Transformación', 'No era yo, era el contexto', 'Creía que el problema era yo. Era [contexto/sistema].', '["identificacion", "revelacion"]', '["emocional", "comunidad"]', '["emocional", "profundo"]', '["todas"]', 2, 'Durante años creí que el problema era que yo no era suficientemente organizada. Era que tenía tres trabajos y uno de ellos no tenía sueldo: la casa.', 'A veces nos culpamos sin razón.', 'Antes y después concretos, sin presumir. El ''cómo'' es lo que se promete.', 'Carrusel antes/después o reel con dos tomas contrastadas.', 'Corte visual de antes a ahora con texto ''hace X tiempo / hoy''.', 'Historia personal con foto real del antes.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('ESC-01', 'Escena narrativa', 'Fecha exacta + escena en curso', 'El [día] de [mes] de [año] estaba [acción] en [lugar] con [detalle]…', '["storytelling", "especificidad", "intriga"]', '["emocional", "posicionamiento"]', '["narrativo", "emocional"]', '["todas"]', 2, 'El 3 de marzo de 2019 estaba en el parqueadero de la empresa, con la carta de renuncia en el bolsillo y sin plan B.', 'Hace unos años tomé una decisión importante.', 'Empieza en mitad de la acción, con un detalle sensorial. El ''ver más'' debe cortar en plena tensión.', 'Reel con voz en off narrando la escena sobre imagen real; o carrusel tipo cómic.', 'Story time: ''les cuento lo que me pasó hoy''. Primer segundo con la frase más tensa de la historia.', 'Formato natural: historia larga con remate.', 'Mecanismo observado: Vilma Núñez, LinkedIn, 2023-09-02 (''El 1 de septiembre de 2015, estaba entrando a Miami…'').', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('ESC-02', 'Escena narrativa', 'Caso ajeno a mitad de camino', 'Una [empresa/persona] quería [objetivo]. Para lograrlo, [decisión que intuimos errada].', '["intriga", "storytelling"]', '["autoridad", "educacion"]', '["narrativo", "experto"]', '["todas"]', 2, 'Una empresa quería bajar la rotación. Para lograrlo, subió todos los salarios. La rotación no se movió.', 'Hay casos interesantes sobre rotación.', 'Empieza en mitad de la acción, con un detalle sensorial. El ''ver más'' debe cortar en plena tensión.', 'Reel con voz en off narrando la escena sobre imagen real; o carrusel tipo cómic.', 'Story time: ''les cuento lo que me pasó hoy''. Primer segundo con la frase más tensa de la historia.', 'Formato natural: historia larga con remate.', 'Mecanismo observado: Jürgen Klarić, LinkedIn, 2021-11-01 (''Una empresa quería vender más relojes…'').', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('ESC-03', 'Escena narrativa', 'Diálogo de apertura', '''[Frase textual de otra persona]''. Así empezó [situación].', '["storytelling", "intriga"]', '["emocional", "alcance"]', '["narrativo", "conversacional"]', '["todas"]', 1, '''¿Usted sabe por qué lo llamé?'' Así empezó la conversación que me cambió la carrera.', 'Una conversación cambió mi carrera.', 'Empieza en mitad de la acción, con un detalle sensorial. El ''ver más'' debe cortar en plena tensión.', 'Reel con voz en off narrando la escena sobre imagen real; o carrusel tipo cómic.', 'Story time: ''les cuento lo que me pasó hoy''. Primer segundo con la frase más tensa de la historia.', 'Formato natural: historia larga con remate.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('ESC-04', 'Escena narrativa', 'El objeto que lo cuenta todo', '[Objeto concreto] fue lo primero que [noté/encontré] cuando [situación].', '["storytelling", "especificidad", "curiosidad"]', '["emocional", "alcance"]', '["narrativo", "profundo"]', '["todas"]', 3, 'Lo primero que vi al entrar a la oficina del gerente fue un tablero lleno de nombres tachados.', 'Al llegar a la empresa noté algunas cosas.', 'Empieza en mitad de la acción, con un detalle sensorial. El ''ver más'' debe cortar en plena tensión.', 'Reel con voz en off narrando la escena sobre imagen real; o carrusel tipo cómic.', 'Story time: ''les cuento lo que me pasó hoy''. Primer segundo con la frase más tensa de la historia.', 'Formato natural: historia larga con remate.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('ESC-05', 'Escena narrativa', 'Apodo o etiqueta cortada', 'Me decían ''[apodo]…'' (corte en el apodo antes del ''ver más'').', '["curiosidad", "storytelling", "identificacion"]', '["alcance", "emocional"]', '["narrativo", "divertido"]', '["todas"]', 2, 'En mi primer trabajo me decían ''el niño del Excel''. No era un cumplido.', 'En mi primer trabajo aprendí mucho.', 'El apodo debe cortarse justo antes del ''ver más'' (≈200 caracteres).', 'Reel con voz en off narrando la escena sobre imagen real; o carrusel tipo cómic.', 'Story time: ''les cuento lo que me pasó hoy''. Primer segundo con la frase más tensa de la historia.', 'Formato natural: historia larga con remate.', 'Mecanismo observado: Jürgen Klarić, LinkedIn, 2021-10-12 (''Por algo me llamaban El niño…'').', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('ESC-06', 'Escena narrativa', 'Lo que pasó en la reunión', 'Ayer en una reunión con [tipo de persona] pasó algo que no esperaba.', '["intriga", "storytelling"]', '["alcance", "conversacion"]', '["conversacional", "narrativo"]', '["todas"]', 1, 'Ayer en una reunión con un CEO pasó algo que no esperaba: me pidió que no le presentara la propuesta.', 'Ayer tuve una reunión interesante.', 'Empieza en mitad de la acción, con un detalle sensorial. El ''ver más'' debe cortar en plena tensión.', 'Reel con voz en off narrando la escena sobre imagen real; o carrusel tipo cómic.', 'Story time: ''les cuento lo que me pasó hoy''. Primer segundo con la frase más tensa de la historia.', 'Formato natural: historia larga con remate.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('ESC-07', 'Escena narrativa', 'Mi hijo/a me enseñó', 'Mi [hijo/a] de [edad] me dijo algo que [efecto]: ''[frase]''.', '["storytelling", "identificacion", "sorpresa"]', '["emocional", "alcance"]', '["emocional", "divertido"]', '["maternidad", "psicologia", "bienestar", "rrhh", "marca_personal"]', 1, 'Mi hija de 7 años me preguntó por qué siempre le digo ''ahorita'' y nunca llega el ahorita.', 'Los niños nos enseñan muchas cosas.', 'Empieza en mitad de la acción, con un detalle sensorial. El ''ver más'' debe cortar en plena tensión.', 'Reel con voz en off narrando la escena sobre imagen real; o carrusel tipo cómic.', 'Story time: ''les cuento lo que me pasó hoy''. Primer segundo con la frase más tensa de la historia.', 'Formato natural: historia larga con remate.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('ESC-08', 'Escena narrativa', 'La llamada', '[Hora] de la [mañana/noche]. Suena el teléfono. Es [persona]. [Primera frase].', '["intriga", "storytelling"]', '["alcance", "emocional"]', '["narrativo"]', '["todas"]', 2, 'Seis y media de la mañana. Suena el teléfono. Es mi mejor cliente: ''Necesito que hablemos hoy, antes de la junta''.', 'Un día recibí una llamada importante.', 'Empieza en mitad de la acción, con un detalle sensorial. El ''ver más'' debe cortar en plena tensión.', 'Reel con voz en off narrando la escena sobre imagen real; o carrusel tipo cómic.', 'Story time: ''les cuento lo que me pasó hoy''. Primer segundo con la frase más tensa de la historia.', 'Formato natural: historia larga con remate.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('ESC-09', 'Escena narrativa', 'Ficción reconocible', 'Imagina que [situación hipotética muy concreta del lector].', '["storytelling", "identificacion"]', '["educacion", "emocional"]', '["narrativo", "educativo"]', '["todas"]', 2, 'Imagina que son las 4 de la tarde, te llaman del colegio y tienes una presentación con el gerente en 20 minutos.', 'Imagina un escenario de estrés laboral.', 'Empieza en mitad de la acción, con un detalle sensorial. El ''ver más'' debe cortar en plena tensión.', 'Reel con voz en off narrando la escena sobre imagen real; o carrusel tipo cómic.', 'Story time: ''les cuento lo que me pasó hoy''. Primer segundo con la frase más tensa de la historia.', 'Formato natural: historia larga con remate.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('ESC-10', 'Escena narrativa', 'Final primero', '[Final inesperado]. Pero para entenderlo hay que volver a [inicio].', '["intriga", "sorpresa"]', '["alcance", "emocional"]', '["narrativo", "provocador"]', '["todas"]', 3, 'Terminé contratando al candidato que peor entrevista hizo. Pero para entenderlo hay que volver a la pregunta que nadie le hizo.', 'Contraté a alguien diferente a lo que esperaba.', 'Empieza en mitad de la acción, con un detalle sensorial. El ''ver más'' debe cortar en plena tensión.', 'Reel con voz en off narrando la escena sobre imagen real; o carrusel tipo cómic.', 'Story time: ''les cuento lo que me pasó hoy''. Primer segundo con la frase más tensa de la historia.', 'Formato natural: historia larga con remate.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('AUT-01', 'Autoridad con criterio', 'Después de X veces', 'Después de [cantidad real] [experiencias], esto es lo que [aprendí/no falla].', '["autoridad", "especificidad"]', '["autoridad", "posicionamiento"]', '["experto", "directo"]', '["todas"]', 1, 'Después de cientos de entrevistas de salida, la razón número uno para irse no aparece en ningún formato.', 'Tengo mucha experiencia en entrevistas.', 'La autoridad se muestra con un criterio que solo tiene alguien con experiencia, no con títulos.', 'Carrusel educativo con criterio propio; la portada muestra la conclusión.', 'Hablar a cámara con un dato de experiencia en el segundo 0 (''he hecho X entrevistas…'').', 'Formato de consejo entre colegas.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('AUT-02', 'Autoridad con criterio', 'Lo que veo desde adentro', 'Desde [posición privilegiada], lo que veo es [observación que el lector no puede ver].', '["autoridad", "revelacion"]', '["autoridad", "posicionamiento"]', '["experto", "intelectual"]', '["todas"]', 2, 'Desde la silla de Recursos Humanos, lo que veo es que la gente no se va por el salario: se va cuando deja de esperar que algo cambie.', 'Desde mi experiencia en RR. HH. he visto muchas cosas.', 'La autoridad se muestra con un criterio que solo tiene alguien con experiencia, no con títulos.', 'Carrusel educativo con criterio propio; la portada muestra la conclusión.', 'Hablar a cámara con un dato de experiencia en el segundo 0 (''he hecho X entrevistas…'').', 'Formato de consejo entre colegas.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('AUT-03', 'Autoridad con criterio', 'La regla que uso', 'Tengo una regla para [situación]: [regla simple].', '["autoridad", "valor_practico"]', '["educacion", "autoridad"]', '["experto", "directo"]', '["todas"]', 1, 'Tengo una regla para contratar: si dudo entre sí y no, es no.', 'Contratar requiere criterio.', 'La autoridad se muestra con un criterio que solo tiene alguien con experiencia, no con títulos.', 'Carrusel educativo con criterio propio; la portada muestra la conclusión.', 'Hablar a cámara con un dato de experiencia en el segundo 0 (''he hecho X entrevistas…'').', 'Formato de consejo entre colegas.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('AUT-04', 'Autoridad con criterio', 'Lo que le pregunto a todo CEO', 'Hay una pregunta que le hago a todo [rol] en la primera reunión: ''[pregunta]''.', '["autoridad", "curiosidad"]', '["leads", "autoridad"]', '["experto", "conversacional"]', '["todas"]', 2, 'Hay una pregunta que le hago a todo CEO en la primera reunión: ''¿qué decisión llevas meses aplazando?''.', 'Hago buenas preguntas en mis reuniones.', 'La autoridad se muestra con un criterio que solo tiene alguien con experiencia, no con títulos.', 'Carrusel educativo con criterio propio; la portada muestra la conclusión.', 'Hablar a cámara con un dato de experiencia en el segundo 0 (''he hecho X entrevistas…'').', 'Formato de consejo entre colegas.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('DAT-06', 'Especificidad y dato', 'Lista con número impar y específico', '[N impar] [cosas] que [resultado], la [número] me tomó [tiempo] entenderla.', '["especificidad", "valor_practico", "curiosidad"]', '["educacion", "alcance"]', '["educativo", "conversacional"]', '["todas"]', 1, 'Siete cosas que aprendí despidiendo gente. La cuarta me tomó diez años entenderla.', 'Lecciones sobre despidos.', 'Solo con datos reales y fuente en el cuerpo. Si no hay dato, usar un detalle de escena.', 'Portada con la cifra grande y la fuente pequeña. Slide final con la referencia.', 'Cifra en pantalla en el segundo 0; en voz, qué significa para el espectador.', 'Dato + pregunta de opinión.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('AUT-05', 'Autoridad con criterio', 'Diagnóstico en una línea', 'Si tu [empresa/equipo] tiene [síntoma], casi siempre es [diagnóstico].', '["autoridad", "revelacion"]', '["leads", "autoridad"]', '["experto", "directo"]', '["todas"]', 1, 'Si tu equipo comercial cumple la meta solo el último día del mes, casi siempre es un problema de cómo diseñaste la comisión.', 'Los equipos comerciales tienen diversos problemas.', 'La autoridad se muestra con un criterio que solo tiene alguien con experiencia, no con títulos.', 'Carrusel educativo con criterio propio; la portada muestra la conclusión.', 'Hablar a cámara con un dato de experiencia en el segundo 0 (''he hecho X entrevistas…'').', 'Formato de consejo entre colegas.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('AUT-06', 'Autoridad con criterio', 'El criterio contraintuitivo del experto', 'Un [experto] no mira [lo obvio]. Mira [detalle no obvio].', '["autoridad", "contradiccion", "moneda_social"]', '["posicionamiento", "educacion"]', '["intelectual", "experto"]', '["todas"]', 2, 'Un buen reclutador no mira la hoja de vida. Mira qué pregunta hace el candidato al final.', 'Los reclutadores evalúan muchos aspectos.', 'La autoridad se muestra con un criterio que solo tiene alguien con experiencia, no con títulos.', 'Carrusel educativo con criterio propio; la portada muestra la conclusión.', 'Hablar a cámara con un dato de experiencia en el segundo 0 (''he hecho X entrevistas…'').', 'Formato de consejo entre colegas.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('AUT-07', 'Autoridad con criterio', 'Lo que haría yo en tu lugar', 'Si fuera [rol del lector] hoy, haría esto el lunes:', '["autoridad", "valor_practico"]', '["leads", "educacion"]', '["directo", "experto"]', '["todas"]', 1, 'Si fuera gerente de una pyme hoy, haría esto el lunes: preguntarle a cada persona qué la haría renunciar.', 'Consejos para gerentes de pymes.', 'La autoridad se muestra con un criterio que solo tiene alguien con experiencia, no con títulos.', 'Carrusel educativo con criterio propio; la portada muestra la conclusión.', 'Hablar a cámara con un dato de experiencia en el segundo 0 (''he hecho X entrevistas…'').', 'Formato de consejo entre colegas.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('AUT-08', 'Autoridad con criterio', 'Lo que no se enseña en la universidad', 'En [formación] te enseñan [teoría]. Nadie te enseña [práctica real].', '["autoridad", "revelacion", "identificacion"]', '["educacion", "alcance"]', '["experto", "conversacional"]', '["todas"]', 1, 'En la universidad te enseñan a hacer un plan de negocio. Nadie te enseña a cobrarle a un amigo.', 'La universidad no enseña todo.', 'La autoridad se muestra con un criterio que solo tiene alguien con experiencia, no con títulos.', 'Carrusel educativo con criterio propio; la portada muestra la conclusión.', 'Hablar a cámara con un dato de experiencia en el segundo 0 (''he hecho X entrevistas…'').', 'Formato de consejo entre colegas.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('AUT-09', 'Autoridad con criterio', 'Predicción con fundamento', 'Mi apuesta para [plazo]: [predicción]. Esto es lo que lo indica: [señal].', '["autoridad", "controversia"]', '["posicionamiento", "conversacion"]', '["intelectual", "experto"]', '["todas"]', 3, 'Mi apuesta para los próximos dos años: el jefe intermedio va a ser el cargo más difícil de llenar. La señal: nadie quiere ser ''el sándwich''.', 'El futuro del trabajo traerá cambios.', 'La autoridad se muestra con un criterio que solo tiene alguien con experiencia, no con títulos.', 'Carrusel educativo con criterio propio; la portada muestra la conclusión.', 'Hablar a cámara con un dato de experiencia en el segundo 0 (''he hecho X entrevistas…'').', 'Formato de consejo entre colegas.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('AUT-10', 'Autoridad con criterio', 'La lista negra del experto', '[N] cosas que ya no acepto en [contexto profesional]:', '["autoridad", "controversia", "valor_practico"]', '["posicionamiento", "alcance"]', '["directo", "provocador"]', '["todas"]', 1, 'Tres cosas que ya no acepto de un cliente: que me pidan propuesta sin reunión, que me pidan descuento antes de saber el precio y que el decisor nunca aparezca.', 'Algunas prácticas de clientes no son buenas.', 'La autoridad se muestra con un criterio que solo tiene alguien con experiencia, no con títulos.', 'Carrusel educativo con criterio propio; la portada muestra la conclusión.', 'Hablar a cámara con un dato de experiencia en el segundo 0 (''he hecho X entrevistas…'').', 'Formato de consejo entre colegas.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('DAT-01', 'Especificidad y dato', 'La cifra que incomoda', '[Dato real con fuente] y casi nadie lo [toma en cuenta].', '["especificidad", "sorpresa"]', '["autoridad", "alcance"]', '["experto", "directo"]', '["todas"]', 2, '[Dato real de tu sector con fuente y año]. Y casi ninguna junta directiva lo tiene en el tablero.', 'Las estadísticas muestran que el tema es importante.', 'Solo con datos reales y fuente en el cuerpo. Si no hay dato, usar un detalle de escena.', 'Portada con la cifra grande y la fuente pequeña. Slide final con la referencia.', 'Cifra en pantalla en el segundo 0; en voz, qué significa para el espectador.', 'Dato + pregunta de opinión.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('DAT-02', 'Especificidad y dato', 'El número pequeño', '[Número pequeño y concreto] [unidad]. Eso es lo que separa [A] de [B].', '["especificidad", "comparacion"]', '["educacion", "alcance"]', '["directo", "experto"]', '["todas"]', 2, 'Cinco minutos. Eso es lo que separa una reunión de feedback útil de una que nadie recuerda: los cinco minutos de preparación.', 'La preparación es importante para el feedback.', 'Solo con datos reales y fuente en el cuerpo. Si no hay dato, usar un detalle de escena.', 'Portada con la cifra grande y la fuente pequeña. Slide final con la referencia.', 'Cifra en pantalla en el segundo 0; en voz, qué significa para el espectador.', 'Dato + pregunta de opinión.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('DAT-03', 'Especificidad y dato', 'Hice la cuenta', 'Hice la cuenta de [algo cotidiano]. El resultado: [resultado concreto de mi propio registro].', '["especificidad", "sorpresa", "identificacion"]', '["alcance", "conversacion"]', '["conversacional", "directo"]', '["todas"]', 2, 'Hice la cuenta de cuántas horas pasé en reuniones el mes pasado. Me alcanzaba para un viaje de diez días.', 'Las reuniones consumen mucho tiempo.', 'Solo con datos reales y fuente en el cuerpo. Si no hay dato, usar un detalle de escena.', 'Portada con la cifra grande y la fuente pequeña. Slide final con la referencia.', 'Cifra en pantalla en el segundo 0; en voz, qué significa para el espectador.', 'Dato + pregunta de opinión.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('DAT-04', 'Especificidad y dato', 'La comparación de magnitud', '[Cosa A] cuesta lo mismo que [cosa B absurda].', '["especificidad", "comparacion", "sorpresa"]', '["alcance", "leads"]', '["provocador", "directo"]', '["todas"]', 2, 'Reemplazar a un gerente que se fue mal puede costar lo mismo que haberle dado un buen jefe durante años.', 'La rotación de gerentes es costosa.', 'Solo con datos reales y fuente en el cuerpo. Si no hay dato, usar un detalle de escena.', 'Portada con la cifra grande y la fuente pequeña. Slide final con la referencia.', 'Cifra en pantalla en el segundo 0; en voz, qué significa para el espectador.', 'Dato + pregunta de opinión.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('DAT-05', 'Especificidad y dato', 'Medí lo que nadie mide', 'Durante [periodo] medí [variable inusual]. Esto encontré.', '["especificidad", "curiosidad", "autoridad"]', '["autoridad", "alcance"]', '["experto", "narrativo"]', '["todas"]', 3, 'Durante un mes anoté cuántas veces mi equipo me pidió permiso para algo que ya podía decidir solo. Esto encontré.', 'Analicé la autonomía de mi equipo.', 'Solo con datos reales y fuente en el cuerpo. Si no hay dato, usar un detalle de escena.', 'Portada con la cifra grande y la fuente pequeña. Slide final con la referencia.', 'Cifra en pantalla en el segundo 0; en voz, qué significa para el espectador.', 'Dato + pregunta de opinión.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('DAT-07', 'Especificidad y dato', 'El detalle sensorial', '[Detalle sensorial de una escena profesional] — y ahí entendí [insight].', '["especificidad", "storytelling"]', '["emocional", "posicionamiento"]', '["narrativo", "profundo"]', '["todas"]', 3, 'El olor a café frío en la sala de juntas a las 9 de la noche, y ahí entendí que la empresa vivía de que nadie se fuera a su casa.', 'Trabajar hasta tarde no es saludable.', 'Solo con datos reales y fuente en el cuerpo. Si no hay dato, usar un detalle de escena.', 'Portada con la cifra grande y la fuente pequeña. Slide final con la referencia.', 'Cifra en pantalla en el segundo 0; en voz, qué significa para el espectador.', 'Dato + pregunta de opinión.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('DAT-08', 'Especificidad y dato', 'Precio en la primera línea', 'Cobro [precio real]. Esto es lo que alguien recibe por eso:', '["especificidad", "autoridad", "confesion"]', '["ventas", "leads"]', '["directo", "comercial"]', '["consultoria", "servicios_profesionales", "marca_personal", "emprendimiento"]', 3, 'Cobro [tu precio real] por un diagnóstico. Esto es lo que una empresa recibe por eso, y por qué la mitad decide no seguir.', 'Nuestros precios son competitivos.', 'Solo con datos reales y fuente en el cuerpo. Si no hay dato, usar un detalle de escena.', 'Portada con la cifra grande y la fuente pequeña. Slide final con la referencia.', 'Cifra en pantalla en el segundo 0; en voz, qué significa para el espectador.', 'Dato + pregunta de opinión.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('DAT-09', 'Especificidad y dato', 'Tiempo concreto, resultado concreto', 'En [tiempo exacto] [resultado verificable]. Sin [lo que todos creen necesario].', '["especificidad", "contradiccion"]', '["alcance", "leads"]', '["directo"]', '["todas"]', 2, 'En tres semanas cerramos la vacante que llevaba seis meses abierta. Sin headhunter: cambiando la descripción del cargo.', 'Logramos cubrir una vacante difícil.', 'Solo con datos reales y fuente en el cuerpo. Si no hay dato, usar un detalle de escena.', 'Portada con la cifra grande y la fuente pequeña. Slide final con la referencia.', 'Cifra en pantalla en el segundo 0; en voz, qué significa para el espectador.', 'Dato + pregunta de opinión.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('DAT-10', 'Especificidad y dato', 'Captura de pantalla', 'Esta es [evidencia concreta que muestro]. Mira [detalle].', '["especificidad", "prueba_social"]', '["ventas", "autoridad"]', '["directo", "comercial"]', '["todas"]', 2, 'Este es el correo que me mandó un cliente un año después del proyecto (con su permiso). Mira la segunda línea.', 'Nuestros clientes están satisfechos.', 'Requiere imagen real (con permiso). Sin evidencia, no usar.', 'Portada con la cifra grande y la fuente pequeña. Slide final con la referencia.', 'Cifra en pantalla en el segundo 0; en voz, qué significa para el espectador.', 'Dato + pregunta de opinión.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('CMP-01', 'Comparación y contraste', 'Puedes tener X y no Y', 'Puedes tener [recurso deseado] y no conseguir [resultado].', '["comparacion", "contradiccion"]', '["autoridad", "conversacion"]', '["directo", "intelectual"]', '["todas"]', 1, 'Puedes tener 80.000 seguidores y no conseguir un solo cliente.', 'Los seguidores no siempre se traducen en clientes.', 'Dos líneas paralelas, misma longitud. La diferencia debe verse sin explicarla.', 'Carrusel en dos columnas o reel con pantalla dividida.', 'Dos tomas: ''persona A'' vs. ''persona B''. Actuar ambos roles.', 'Comparación + ''¿cuál eres tú?''.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('CMP-02', 'Comparación y contraste', 'A hace esto, B hace aquello', 'Un [rol mediocre] [acción]. Un [rol excelente] [acción distinta].', '["comparacion", "aspiracion"]', '["educacion", "posicionamiento"]', '["directo", "experto"]', '["todas"]', 1, 'Un jefe pregunta ''¿por qué no está listo?''. Un líder pregunta ''¿qué te está frenando?''.', 'Hay diferencias entre jefes y líderes.', 'Dos líneas paralelas, misma longitud. La diferencia debe verse sin explicarla.', 'Carrusel en dos columnas o reel con pantalla dividida.', 'Dos tomas: ''persona A'' vs. ''persona B''. Actuar ambos roles.', 'Comparación + ''¿cuál eres tú?''.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('CMP-03', 'Comparación y contraste', 'Antes / ahora del sector', 'Antes [sector] era [X]. Ahora es [Y]. Y [consecuencia para el lector].', '["comparacion", "advertencia"]', '["posicionamiento", "conversacion"]', '["intelectual", "conversacional"]', '["todas"]', 2, 'Antes LinkedIn era para buscar trabajo. Ahora parece Instagram con corbata. Y algunos siguen consiguiendo clientes ahí, callados.', 'LinkedIn ha cambiado mucho.', 'Dos líneas paralelas, misma longitud. La diferencia debe verse sin explicarla.', 'Carrusel en dos columnas o reel con pantalla dividida.', 'Dos tomas: ''persona A'' vs. ''persona B''. Actuar ambos roles.', 'Comparación + ''¿cuál eres tú?''.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('CMP-04', 'Comparación y contraste', 'Lo que crees que hace vs. lo que hace', 'Lo que crees que hace un [rol]: [imagen]. Lo que hace de verdad: [realidad].', '["comparacion", "humor", "revelacion"]', '["alcance", "comunidad"]', '["divertido", "conversacional"]', '["todas"]', 1, 'Lo que crees que hace alguien de RR. HH.: fiestas de fin de año. Lo que hace de verdad: evitar demandas a las 7 de la noche.', 'El trabajo de RR. HH. es poco comprendido.', 'Dos líneas paralelas, misma longitud. La diferencia debe verse sin explicarla.', 'Carrusel en dos columnas o reel con pantalla dividida.', 'Dos tomas: ''persona A'' vs. ''persona B''. Actuar ambos roles.', 'Comparación + ''¿cuál eres tú?''.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('CMP-05', 'Comparación y contraste', 'Dos clientes, dos destinos', 'Tuve dos clientes con el mismo problema. Uno [decisión A], el otro [decisión B]. Hoy [resultados].', '["comparacion", "storytelling", "prueba_social"]', '["leads", "ventas"]', '["narrativo", "experto"]', '["todas"]', 2, 'Tuve dos clientes con el mismo problema de rotación. Uno subió salarios; el otro cambió a dos gerentes. Hoy solo uno sigue perdiendo gente.', 'Distintas decisiones llevan a distintos resultados.', 'Dos líneas paralelas, misma longitud. La diferencia debe verse sin explicarla.', 'Carrusel en dos columnas o reel con pantalla dividida.', 'Dos tomas: ''persona A'' vs. ''persona B''. Actuar ambos roles.', 'Comparación + ''¿cuál eres tú?''.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('CMP-06', 'Comparación y contraste', 'Lo barato vs. lo caro (de verdad)', 'Lo barato es [opción aparente]. Lo caro es [costo real de esa opción].', '["comparacion", "miedo_perder"]', '["ventas", "leads"]', '["directo", "comercial"]', '["todas"]', 1, 'Lo barato es seguir con el gerente que todos sabemos que no funciona. Lo caro es todo lo que ese equipo deja de vender mientras tanto.', 'Invertir en buenos gerentes es importante.', 'Dos líneas paralelas, misma longitud. La diferencia debe verse sin explicarla.', 'Carrusel en dos columnas o reel con pantalla dividida.', 'Dos tomas: ''persona A'' vs. ''persona B''. Actuar ambos roles.', 'Comparación + ''¿cuál eres tú?''.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('CMP-07', 'Comparación y contraste', 'Yo a los 25 vs. yo hoy', 'Yo a los [edad] pensaba [X]. Yo hoy pienso [Y].', '["comparacion", "confesion", "identificacion"]', '["emocional", "alcance"]', '["conversacional", "profundo"]', '["todas"]', 1, 'Yo a los 25: ''el que más horas trabaja, más crece''. Yo hoy: ''el que mejor decide qué no hacer, crece''.', 'He cambiado mi forma de pensar con los años.', 'Dos líneas paralelas, misma longitud. La diferencia debe verse sin explicarla.', 'Carrusel en dos columnas o reel con pantalla dividida.', 'Dos tomas: ''persona A'' vs. ''persona B''. Actuar ambos roles.', 'Comparación + ''¿cuál eres tú?''.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('CMP-08', 'Comparación y contraste', 'La misma frase, dos efectos', '''[Frase]'' dicha por [A] suena a [X]. Dicha por [B] suena a [Y].', '["comparacion", "revelacion"]', '["educacion", "conversacion"]', '["intelectual", "conversacional"]', '["todas"]', 3, '''Confío en ti'', dicho por un jefe que nunca revisa nada, suena a abandono. Dicho por uno que estuvo al lado, suena a ascenso.', 'Las palabras dependen del contexto.', 'Dos líneas paralelas, misma longitud. La diferencia debe verse sin explicarla.', 'Carrusel en dos columnas o reel con pantalla dividida.', 'Dos tomas: ''persona A'' vs. ''persona B''. Actuar ambos roles.', 'Comparación + ''¿cuál eres tú?''.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('CMP-09', 'Comparación y contraste', 'Lo que ven ellos vs. lo que ves tú', 'Tu [cliente/equipo] ve [percepción]. Tú ves [tu percepción]. El problema está en el medio.', '["comparacion", "revelacion", "identificacion"]', '["leads", "autoridad"]', '["experto", "directo"]', '["todas"]', 2, 'Tu equipo ve un jefe que cambia de opinión cada semana. Tú ves un mercado que cambia cada semana. El problema es que nadie se lo explicó a ellos.', 'Hay diferencias de percepción en los equipos.', 'Dos líneas paralelas, misma longitud. La diferencia debe verse sin explicarla.', 'Carrusel en dos columnas o reel con pantalla dividida.', 'Dos tomas: ''persona A'' vs. ''persona B''. Actuar ambos roles.', 'Comparación + ''¿cuál eres tú?''.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('CMP-10', 'Comparación y contraste', 'El ranking honesto', 'De peor a mejor forma de [acción]: [lista corta con humor].', '["comparacion", "humor", "valor_practico"]', '["alcance", "comentarios"]', '["divertido", "directo"]', '["todas"]', 1, 'De peor a mejor forma de pedir un aumento: 1) por indirectas, 2) comparándote con el compañero, 3) llegando con lo que lograste este año.', 'Consejos para pedir un aumento.', 'Dos líneas paralelas, misma longitud. La diferencia debe verse sin explicarla.', 'Carrusel en dos columnas o reel con pantalla dividida.', 'Dos tomas: ''persona A'' vs. ''persona B''. Actuar ambos roles.', 'Comparación + ''¿cuál eres tú?''.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('TRI-01', 'Pertenencia y tribu', 'Esto es para los que…', 'Esto es para los que [rasgo muy específico].', '["pertenencia", "identificacion"]', '["comunidad", "emocional"]', '["conversacional", "emocional"]', '["todas"]', 1, 'Esto es para las que se sienten culpables cuando se toman un café solas.', 'Este contenido es para mujeres profesionales.', 'Nombrar a la tribu con un rasgo concreto, no con una etiqueta genérica.', 'Contenido para compartir: ''esto es para las que…''.', 'Texto en pantalla ''si eres X, ya sabes''; tendencias de audio con situación propia.', 'Funciona en grupos: invita a etiquetar a ''los tuyos''.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('TRI-02', 'Pertenencia y tribu', 'Los que somos X sabemos', 'Los que [experiencia compartida] sabemos que [verdad interna].', '["pertenencia", "humor"]', '["comunidad", "alcance"]', '["divertido", "conversacional"]', '["todas"]', 1, 'Los que hemos trabajado en una pyme sabemos que ''eso no es mi función'' no existe.', 'Trabajar en pymes tiene sus particularidades.', 'Nombrar a la tribu con un rasgo concreto, no con una etiqueta genérica.', 'Contenido para compartir: ''esto es para las que…''.', 'Texto en pantalla ''si eres X, ya sabes''; tendencias de audio con situación propia.', 'Funciona en grupos: invita a etiquetar a ''los tuyos''.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('TRI-03', 'Pertenencia y tribu', 'Carta a mi gremio', 'Querido/a [gremio]: tenemos que hablar de [tema incómodo].', '["pertenencia", "controversia"]', '["conversacion", "posicionamiento"]', '["directo", "provocador"]', '["todas"]', 2, 'Querida gente de Recursos Humanos: tenemos que hablar de por qué nadie nos invita a la reunión de estrategia.', 'Reflexión para profesionales de RR. HH.', 'Nombrar a la tribu con un rasgo concreto, no con una etiqueta genérica.', 'Contenido para compartir: ''esto es para las que…''.', 'Texto en pantalla ''si eres X, ya sabes''; tendencias de audio con situación propia.', 'Funciona en grupos: invita a etiquetar a ''los tuyos''.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('TRI-04', 'Pertenencia y tribu', 'El código interno', 'Si entiendes [referencia interna], eres de los míos.', '["pertenencia", "humor", "moneda_social"]', '["comunidad", "alcance"]', '["divertido", "irreverente"]', '["todas"]', 2, 'Si sabes lo que significa ''lo dejamos en el parqueadero'', eres de los míos.', 'Hay expresiones que solo entienden algunos.', 'Nombrar a la tribu con un rasgo concreto, no con una etiqueta genérica.', 'Contenido para compartir: ''esto es para las que…''.', 'Texto en pantalla ''si eres X, ya sabes''; tendencias de audio con situación propia.', 'Funciona en grupos: invita a etiquetar a ''los tuyos''.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('TRI-05', 'Pertenencia y tribu', 'Ellos vs. nosotros (sobre prácticas)', 'Hay quienes [práctica criticada]. Y estamos los que [práctica propia].', '["pertenencia", "enemigo_comun"]', '["posicionamiento", "comunidad"]', '["provocador", "directo"]', '["todas"]', 2, 'Hay quienes miden la productividad por la hora de salida. Y estamos los que la medimos por lo que se terminó.', 'Hay distintas formas de medir la productividad.', 'Nombrar a la tribu con un rasgo concreto, no con una etiqueta genérica.', 'Contenido para compartir: ''esto es para las que…''.', 'Texto en pantalla ''si eres X, ya sabes''; tendencias de audio con situación propia.', 'Funciona en grupos: invita a etiquetar a ''los tuyos''.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('TRI-06', 'Pertenencia y tribu', 'Lo que no te dicen cuando eres el único', 'Cuando eres el/la único/a [rasgo] en [lugar], [experiencia].', '["pertenencia", "identificacion", "revelacion"]', '["emocional", "comunidad"]', '["profundo", "emocional"]', '["todas"]', 2, 'Cuando eres la única mujer en la junta directiva, aprendes a decir las cosas dos veces: una para que te escuchen y otra para que no se la atribuyan a otro.', 'Las mujeres enfrentan retos en las juntas directivas.', 'Nombrar a la tribu con un rasgo concreto, no con una etiqueta genérica.', 'Contenido para compartir: ''esto es para las que…''.', 'Texto en pantalla ''si eres X, ya sabes''; tendencias de audio con situación propia.', 'Funciona en grupos: invita a etiquetar a ''los tuyos''.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('TRI-07', 'Pertenencia y tribu', 'Orgullo de origen', 'Soy de [lugar/origen] y eso me enseñó [lección profesional].', '["pertenencia", "storytelling", "autoridad"]', '["posicionamiento", "emocional"]', '["narrativo", "inspirador"]', '["todas"]', 1, 'Viví casi cuatro años en Villavicencio y el llano me enseñó lo que ningún MBA: un negocio se cierra con la palabra, y se pierde con la letra pequeña.', 'Mi origen ha influido en mi carrera.', 'Nombrar a la tribu con un rasgo concreto, no con una etiqueta genérica.', 'Contenido para compartir: ''esto es para las que…''.', 'Texto en pantalla ''si eres X, ya sabes''; tendencias de audio con situación propia.', 'Funciona en grupos: invita a etiquetar a ''los tuyos''.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('TRI-08', 'Pertenencia y tribu', 'Bienvenida al club', 'Bienvenido/a al club de los que [experiencia difícil]. Esto es lo que nadie te dice:', '["pertenencia", "valor_practico"]', '["comunidad", "educacion"]', '["conversacional", "emocional"]', '["todas"]', 1, 'Bienvenida al club de las que volvieron al trabajo después de la licencia de maternidad. Esto es lo que nadie te dice:', 'Consejos para volver al trabajo.', 'Nombrar a la tribu con un rasgo concreto, no con una etiqueta genérica.', 'Contenido para compartir: ''esto es para las que…''.', 'Texto en pantalla ''si eres X, ya sabes''; tendencias de audio con situación propia.', 'Funciona en grupos: invita a etiquetar a ''los tuyos''.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('TRI-09', 'Pertenencia y tribu', 'La pregunta de la tribu', 'Pregunta para los que [rasgo]: ¿[pregunta específica que solo ellos responden]?', '["pertenencia", "curiosidad"]', '["comentarios", "comunidad"]', '["conversacional"]', '["todas"]', 1, 'Pregunta para los que manejan equipos remotos: ¿cómo se dan cuenta de que alguien está mal si nunca prende la cámara?', '¿Qué opinan del trabajo remoto?', 'Nombrar a la tribu con un rasgo concreto, no con una etiqueta genérica.', 'Contenido para compartir: ''esto es para las que…''.', 'Texto en pantalla ''si eres X, ya sabes''; tendencias de audio con situación propia.', 'Funciona en grupos: invita a etiquetar a ''los tuyos''.', '', true);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('TRI-10', 'Pertenencia y tribu', 'Manifiesto corto', 'Creemos en [principio]. No creemos en [práctica rechazada].', '["pertenencia", "controversia", "aspiracion"]', '["posicionamiento", "comunidad"]', '["inspirador", "directo"]', '["todas"]', 2, 'Creemos en jefes que dicen ''no sé''. No creemos en jefes que inventan para no quedar mal.', 'Nuestros valores son la honestidad y la transparencia.', 'Nombrar a la tribu con un rasgo concreto, no con una etiqueta genérica.', 'Contenido para compartir: ''esto es para las que…''.', 'Texto en pantalla ''si eres X, ya sabes''; tendencias de audio con situación propia.', 'Funciona en grupos: invita a etiquetar a ''los tuyos''.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('UTI-01', 'Valor práctico', 'Haz esto mañana', 'Mañana, en tu [momento], haz esto: [acción concreta].', '["valor_practico", "especificidad"]', '["educacion", "alcance"]', '["directo", "educativo"]', '["todas"]', 1, 'Mañana, en tu primera reunión, haz esto: antes de dar tu opinión, pregunta ''¿qué opinas tú?'' y cuenta hasta cinco.', 'Consejos para mejorar tus reuniones.', 'Promesa útil y concreta; el cuerpo debe entregarla en pasos. Nada de ''tips'' genéricos.', 'Carrusel guardable: portada con el resultado, un paso por slide.', 'Tutorial rápido: ''haz esto mañana''. Mostrar el paso, no describirlo.', 'Formato lista con ejemplo propio.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('UTI-02', 'Valor práctico', 'La plantilla que uso', 'Esta es la [plantilla/frase/correo] exacto que uso para [situación difícil].', '["valor_practico", "autoridad"]', '["leads", "educacion"]', '["experto", "directo"]', '["todas"]', 1, 'Este es el mensaje exacto que uso cuando un cliente lleva tres semanas sin responder. No falla, y no suena a cobrador.', 'Aquí tienes una plantilla de seguimiento.', 'Promesa útil y concreta; el cuerpo debe entregarla en pasos. Nada de ''tips'' genéricos.', 'Carrusel guardable: portada con el resultado, un paso por slide.', 'Tutorial rápido: ''haz esto mañana''. Mostrar el paso, no describirlo.', 'Formato lista con ejemplo propio.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('UTI-03', 'Valor práctico', 'Una pregunta en vez de diez', 'Si solo pudieras hacer una pregunta en [situación], haz esta: ''[pregunta]''.', '["valor_practico", "curiosidad"]', '["educacion", "autoridad"]', '["experto", "conversacional"]', '["todas"]', 1, 'Si solo pudieras hacer una pregunta en una entrevista de trabajo, haz esta: ''¿Qué fue lo último que aprendiste por tu cuenta?''.', 'Las preguntas en entrevistas son importantes.', 'Promesa útil y concreta; el cuerpo debe entregarla en pasos. Nada de ''tips'' genéricos.', 'Carrusel guardable: portada con el resultado, un paso por slide.', 'Tutorial rápido: ''haz esto mañana''. Mostrar el paso, no describirlo.', 'Formato lista con ejemplo propio.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('UTI-04', 'Valor práctico', 'El atajo honesto', 'No existe un atajo para [X]. Pero sí uno para [sub-X concreto]:', '["valor_practico", "contradiccion"]', '["educacion", "alcance"]', '["directo", "conversacional"]', '["todas"]', 2, 'No existe un atajo para tener un buen equipo. Pero sí uno para saber si lo tienes: pregúntales qué harían si fueran tú.', 'Construir equipos toma tiempo.', 'Promesa útil y concreta; el cuerpo debe entregarla en pasos. Nada de ''tips'' genéricos.', 'Carrusel guardable: portada con el resultado, un paso por slide.', 'Tutorial rápido: ''haz esto mañana''. Mostrar el paso, no describirlo.', 'Formato lista con ejemplo propio.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('UTI-05', 'Valor práctico', 'Checklist de 3', 'Antes de [acción], revisa estas 3 cosas:', '["valor_practico", "advertencia"]', '["educacion", "leads"]', '["educativo", "directo"]', '["todas"]', 1, 'Antes de mandar una propuesta, revisa tres cosas: ¿hablé con quien decide?, ¿sé qué pasa si no hace nada?, ¿el precio está al final o al principio?', 'Revisa tus propuestas antes de enviarlas.', 'Promesa útil y concreta; el cuerpo debe entregarla en pasos. Nada de ''tips'' genéricos.', 'Carrusel guardable: portada con el resultado, un paso por slide.', 'Tutorial rápido: ''haz esto mañana''. Mostrar el paso, no describirlo.', 'Formato lista con ejemplo propio.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('UTI-06', 'Valor práctico', 'Cambia esta frase por esta', 'Deja de decir ''[frase débil]''. Di ''[frase fuerte]''.', '["valor_practico", "comparacion"]', '["alcance", "educacion"]', '["directo", "conversacional"]', '["todas"]', 1, 'Deja de decir ''perdón por molestar''. Di ''tengo algo que te puede servir''.', 'La forma de comunicarnos importa.', 'Promesa útil y concreta; el cuerpo debe entregarla en pasos. Nada de ''tips'' genéricos.', 'Carrusel guardable: portada con el resultado, un paso por slide.', 'Tutorial rápido: ''haz esto mañana''. Mostrar el paso, no describirlo.', 'Formato lista con ejemplo propio.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('UTI-07', 'Valor práctico', 'El ejercicio de 5 minutos', 'Un ejercicio de [tiempo] para [resultado emocional/práctico]:', '["valor_practico", "identificacion"]', '["educacion", "comunidad"]', '["educativo", "emocional"]', '["psicologia", "bienestar", "maternidad", "rrhh"]', 1, 'Un ejercicio de cinco minutos para cuando llegas a la casa y todavía tienes la cabeza en la oficina:', 'Ejercicios de relajación para profesionales.', 'Promesa útil y concreta; el cuerpo debe entregarla en pasos. Nada de ''tips'' genéricos.', 'Carrusel guardable: portada con el resultado, un paso por slide.', 'Tutorial rápido: ''haz esto mañana''. Mostrar el paso, no describirlo.', 'Formato lista con ejemplo propio.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('UTI-08', 'Valor práctico', 'Lo que haría con 0 presupuesto', 'Si tuviera que [lograr X] sin un peso, haría esto:', '["valor_practico", "especificidad", "aspiracion"]', '["educacion", "alcance"]', '["directo", "experto"]', '["todas"]', 1, 'Si tuviera que mejorar el clima de un equipo sin un peso de presupuesto, haría esto la primera semana:', 'Ideas económicas para mejorar el clima laboral.', 'Promesa útil y concreta; el cuerpo debe entregarla en pasos. Nada de ''tips'' genéricos.', 'Carrusel guardable: portada con el resultado, un paso por slide.', 'Tutorial rápido: ''haz esto mañana''. Mostrar el paso, no describirlo.', 'Formato lista con ejemplo propio.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('UTI-09', 'Valor práctico', 'El método con nombre propio', 'Le digo ''[nombre propio del método]'': [explicación en una línea].', '["valor_practico", "autoridad", "moneda_social"]', '["posicionamiento", "autoridad"]', '["experto", "conversacional"]', '["todas"]', 2, 'Le digo ''la regla del viernes'': nada que importe se decide un viernes después de las 3.', 'Tengo un método para tomar decisiones.', 'Promesa útil y concreta; el cuerpo debe entregarla en pasos. Nada de ''tips'' genéricos.', 'Carrusel guardable: portada con el resultado, un paso por slide.', 'Tutorial rápido: ''haz esto mañana''. Mostrar el paso, no describirlo.', 'Formato lista con ejemplo propio.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('UTI-10', 'Valor práctico', 'Guárdalo para cuando…', 'Guarda esto para el día que [situación futura probable].', '["valor_practico", "identificacion"]', '["alcance", "comunidad"]', '["conversacional", "emocional"]', '["todas"]', 1, 'Guarda esto para el día que tu jefe te pida ''algo rápido'' a las 5:45 de la tarde.', 'Consejos para manejar a tu jefe.', 'Promesa útil y concreta; el cuerpo debe entregarla en pasos. Nada de ''tips'' genéricos.', 'Ideal para guardados: portada ''guárdalo para cuando…''.', 'Tutorial rápido: ''haz esto mañana''. Mostrar el paso, no describirlo.', 'Formato lista con ejemplo propio.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('META-01', 'Meta y formato', 'Hablarle al que está deslizando', 'Sí, tú, el que está [acción en ese momento]: [mensaje].', '["sorpresa", "identificacion", "humor"]', '["alcance"]', '["irreverente", "divertido"]', '["todas"]', 2, 'Sí, tú, que estás leyendo esto en una reunión con la cámara apagada: esto también es para ti.', 'Este post es para todos los profesionales.', 'Rompe la expectativa del formato del feed. Usar con moderación: el truco se gasta.', 'Juega con el formato: carrusel que ''no se debería deslizar'', reel que empieza por el final.', 'Romper la cuarta pared: hablarle al que está a punto de deslizar.', 'Funciona menos; usar solo con humor claro.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('META-02', 'Meta y formato', 'El post que no quería escribir', 'Este es el post que llevo [tiempo] sin querer escribir.', '["intriga", "confesion"]', '["emocional", "alcance"]', '["emocional", "narrativo"]', '["todas"]', 2, 'Este es el post que llevo un año sin querer escribir.', 'Hoy quiero compartir algo importante.', 'Rompe la expectativa del formato del feed. Usar con moderación: el truco se gasta.', 'Juega con el formato: carrusel que ''no se debería deslizar'', reel que empieza por el final.', 'Romper la cuarta pared: hablarle al que está a punto de deslizar.', 'Funciona menos; usar solo con humor claro.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('META-03', 'Meta y formato', 'Respuesta pública', 'Alguien me preguntó [pregunta real]. La respuesta corta es [X]. La larga:', '["curiosidad", "autoridad", "prueba_social"]', '["educacion", "comunidad"]', '["conversacional", "experto"]', '["todas"]', 1, 'Alguien me preguntó por mensaje si vale la pena renunciar sin tener otro trabajo. La respuesta corta es: depende de una sola cosa. La larga:', 'Me hacen muchas preguntas sobre renunciar.', 'Rompe la expectativa del formato del feed. Usar con moderación: el truco se gasta.', 'Juega con el formato: carrusel que ''no se debería deslizar'', reel que empieza por el final.', 'Romper la cuarta pared: hablarle al que está a punto de deslizar.', 'Funciona menos; usar solo con humor claro.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('META-04', 'Meta y formato', 'Corregir un post anterior', 'Hace [tiempo] publiqué [idea]. Hoy la corrijo.', '["confesion", "autoridad", "contradiccion"]', '["autoridad", "conversacion"]', '["intelectual", "conversacional"]', '["todas"]', 2, 'Hace un año publiqué que el trabajo remoto era el futuro para todos. Hoy lo corrijo.', 'He cambiado de opinión sobre algunos temas.', 'Rompe la expectativa del formato del feed. Usar con moderación: el truco se gasta.', 'Juega con el formato: carrusel que ''no se debería deslizar'', reel que empieza por el final.', 'Romper la cuarta pared: hablarle al que está a punto de deslizar.', 'Funciona menos; usar solo con humor claro.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('META-05', 'Meta y formato', 'La plantilla del gurú, desmontada', '[Frase típica de gurú]. Así no se empieza un post. Así sí:', '["satira", "valor_practico", "moneda_social"]', '["educacion", "posicionamiento"]', '["irreverente", "experto"]', '["marketing", "marca_personal", "ventas"]', 2, '''En el dinámico mundo de hoy, la marca personal es fundamental.'' Así no se empieza un post. Así sí:', 'Consejos para escribir mejores posts.', 'Rompe la expectativa del formato del feed. Usar con moderación: el truco se gasta.', 'Juega con el formato: carrusel que ''no se debería deslizar'', reel que empieza por el final.', 'Romper la cuarta pared: hablarle al que está a punto de deslizar.', 'Funciona menos; usar solo con humor claro.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('META-06', 'Meta y formato', 'Spoiler primero', 'Spoiler: [conclusión]. Ahora te cuento por qué.', '["sorpresa", "curiosidad"]', '["alcance", "educacion"]', '["directo", "conversacional"]', '["todas"]', 1, 'Spoiler: el cliente nunca se quejó del precio. Ahora te cuento por qué casi lo pierdo igual.', 'Te voy a contar una historia con un cliente.', 'Rompe la expectativa del formato del feed. Usar con moderación: el truco se gasta.', 'Juega con el formato: carrusel que ''no se debería deslizar'', reel que empieza por el final.', 'Romper la cuarta pared: hablarle al que está a punto de deslizar.', 'Funciona menos; usar solo con humor claro.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('META-07', 'Meta y formato', 'Lo que borraron los comentarios', 'En mi último post, [comentario recurrente]. Tienen razón en algo: [concesión].', '["prueba_social", "confesion", "contradiccion"]', '["conversacion", "comunidad"]', '["conversacional", "intelectual"]', '["todas"]', 2, 'En mi último post, varios me dijeron que exageraba con lo de los jefes. Tienen razón en algo: no conté la parte en que el jefe era yo.', 'Gracias por sus comentarios en mi último post.', 'Rompe la expectativa del formato del feed. Usar con moderación: el truco se gasta.', 'Juega con el formato: carrusel que ''no se debería deslizar'', reel que empieza por el final.', 'Romper la cuarta pared: hablarle al que está a punto de deslizar.', 'Funciona menos; usar solo con humor claro.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('META-08', 'Meta y formato', 'La palabra sola', '[Una palabra]. [Punto]. (La palabra define el post.)', '["sorpresa", "curiosidad"]', '["alcance", "emocional"]', '["directo", "profundo"]', '["todas"]', 3, 'Culpa. Esa es la palabra que más escucho de mamás que trabajan. Y casi nunca es suya.', 'Hoy quiero hablar de la culpa.', 'Rompe la expectativa del formato del feed. Usar con moderación: el truco se gasta.', 'Juega con el formato: carrusel que ''no se debería deslizar'', reel que empieza por el final.', 'Romper la cuarta pared: hablarle al que está a punto de deslizar.', 'Funciona menos; usar solo con humor claro.', '', false);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('META-09', 'Meta y formato', 'Pregunta con respuesta incómoda', 'Respóndete en silencio: ¿[pregunta personal incómoda]?', '["identificacion", "curiosidad", "advertencia"]', '["emocional", "conversacion"]', '["profundo", "confrontacional"]', '["todas"]', 2, 'Respóndete en silencio: ¿tu equipo te cuenta los problemas o te enteras por otro lado?', '¿Tu equipo confía en ti?', 'Rompe la expectativa del formato del feed. Usar con moderación: el truco se gasta.', 'Juega con el formato: carrusel que ''no se debería deslizar'', reel que empieza por el final.', 'Romper la cuarta pared: hablarle al que está a punto de deslizar.', 'Funciona menos; usar solo con humor claro.', '', true);
INSERT INTO public.structures (code, family, name, formula, mechanisms, objective, tones, industries, difficulty, example, counter_example, adapt_linkedin, adapt_instagram, adapt_tiktok, adapt_facebook, reference, is_question) VALUES ('META-10', 'Meta y formato', 'Anuncio que no es anuncio', 'Tengo una noticia: [anuncio que en realidad es una lección/opinión].', '["sorpresa", "ironia"]', '["alcance", "posicionamiento"]', '["irreverente", "divertido"]', '["todas"]', 2, 'Tengo una noticia: este año no voy a lanzar nada nuevo. Voy a vender mejor lo que ya tengo.', 'Este año me voy a enfocar en mis productos actuales.', 'Rompe la expectativa del formato del feed. Usar con moderación: el truco se gasta.', 'Juega con el formato: carrusel que ''no se debería deslizar'', reel que empieza por el final.', 'Romper la cuarta pared: hablarle al que está a punto de deslizar.', 'Funciona menos; usar solo con humor claro.', '', false);

