ALTER TABLE ONLY public.brands
    ADD CONSTRAINT brands_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.brands
    ADD CONSTRAINT brands_slug_unique UNIQUE (slug);

ALTER TABLE ONLY public.contents
    ADD CONSTRAINT contents_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.creators
    ADD CONSTRAINT creators_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.creators
    ADD CONSTRAINT creators_slug_unique UNIQUE (slug);

ALTER TABLE ONLY public.generated_hooks
    ADD CONSTRAINT generated_hooks_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.generations
    ADD CONSTRAINT generations_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.industries
    ADD CONSTRAINT industries_pkey PRIMARY KEY (code);

ALTER TABLE ONLY public.llm_calls
    ADD CONSTRAINT llm_calls_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.mechanisms
    ADD CONSTRAINT mechanisms_pkey PRIMARY KEY (code);

ALTER TABLE ONLY public.observed_hooks
    ADD CONSTRAINT observed_hooks_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.prompt_versions
    ADD CONSTRAINT prompt_versions_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.structures
    ADD CONSTRAINT structures_pkey PRIMARY KEY (code);

CREATE INDEX hooks_generation ON public.generated_hooks USING btree (generation_id);

CREATE UNIQUE INDEX prompt_key_version ON public.prompt_versions USING btree (key, version);

ALTER TABLE ONLY public.contents
    ADD CONSTRAINT contents_hook_id_generated_hooks_id_fk FOREIGN KEY (hook_id) REFERENCES public.generated_hooks(id) ON DELETE CASCADE;

ALTER TABLE ONLY public.generated_hooks
    ADD CONSTRAINT generated_hooks_generation_id_generations_id_fk FOREIGN KEY (generation_id) REFERENCES public.generations(id) ON DELETE CASCADE;

ALTER TABLE ONLY public.generations
    ADD CONSTRAINT generations_brand_id_brands_id_fk FOREIGN KEY (brand_id) REFERENCES public.brands(id);

ALTER TABLE ONLY public.observed_hooks
    ADD CONSTRAINT observed_hooks_creator_id_creators_id_fk FOREIGN KEY (creator_id) REFERENCES public.creators(id);

